INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u2-C1','math',1,1,'u2',2,'생활 속 물건을 모양대로 나누기 — 주변 물건을 상자·기둥·공 모양으로 찾고 나누되, 크기·색깔·이름·쓰임·놓인 방향이 아니라 생김새로 가르기',ARRAY['2수03-01']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u2-C2','math',1,1,'u2',3,'모양의 부분 알기 — 상자는 평평한·뾰족한 부분, 기둥은 평평한 위·아래와 둥근 옆, 공은 둥근 부분만 있음을 알고, 한 가지 부분만으로 서둘러 정하지 않기',ARRAY['2수03-01']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u2-C3','math',1,1,'u2',3,'쌓기와 굴리기 — 상자는 잘 쌓이고 굴러가지 않으며, 기둥은 세우면 쌓이고 눕히면 한 방향으로 굴러가며, 공은 쌓을 수 없고 여러 방향으로 굴러감을 알기',ARRAY['2수03-01']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u2-C4','math',1,1,'u2',4,'모양으로 만들기 — 바퀴·자리·탑·울타리처럼 쓰임에 어울리는 모양을 특징을 까닭으로 골라 쓰고, 만든 것에 쓴 모양을 빠뜨리지 않고 세기',ARRAY['2수03-01']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-1-u2-C5','math',1,1,'u2',5,'모양을 견주고 알아맞히기 — 두 물건의 같은 점·다른 점을 모양으로 말하고, 일부만 보거나 만지거나 설명만 듣고 모양을 알아맞히되, 단서가 모자라면 알 수 있는 것까지만 말하기',ARRAY['2수03-01']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X01','math',1,'u2',ARRAY['M1-1-u2-C1','M1-1-u2-C5']::text[],'크기·색깔로 모양을 가른다 — 큰 택배 상자와 작은 주사위, 축구공과 구슬을 서로 다른 모양이라고 함','크기만 다른 두 물건을 나란히 놓고 「평평한 곳·뾰족한 곳·둥근 곳」을 하나씩 짚어 견주게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X02','math',1,'u2',ARRAY['M1-1-u2-C1']::text[],'물건 이름이나 쓰임으로 모양을 정한다 — 「필통은 다 상자 모양」, 이름에 「공」이 없는 구슬·수박을 공 모양이 아니라고 함','이름을 가리고 그림자(실루엣)만 보여 준 뒤 모양을 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X03','math',1,'u2',ARRAY['M1-1-u2-C1','M1-1-u2-C4']::text[],'놓인 방향이 바뀌면 다른 모양이라고 한다 — 누운 기둥(통나무·건전지)을 기둥 모양으로 보지 못함','휴지 심을 세웠다 눕혔다 하며 「평평한 곳과 둥근 곳이 그대로 있나?」 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X04','math',1,'u2',ARRAY['M1-1-u2-C1','M1-1-u2-C2','M1-1-u2-C5']::text[],'둥근 부분이 보이면 모두 공 모양이라고 한다 — 기둥과 공을 섞음','통조림과 공을 굴려 보고, 평평한 곳이 있는지 손바닥으로 눌러 보게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X05','math',1,'u2',ARRAY['M1-1-u2-C2','M1-1-u2-C5']::text[],'평평한 부분이 있으면 모두 상자 모양이라고 한다 — 기둥의 평평한 위·아래만 보고 상자라고 함','상자와 기둥을 위에서만 내려다보게 한 뒤 옆으로 돌려 둥근 옆을 보여 주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X06','math',1,'u2',ARRAY['M1-1-u2-C2']::text[],'모양의 부분이 있고 없음을 잘못 짚는다 — 공에도 평평한 곳이, 기둥에도 뾰족한 곳이 있다고 함','눈을 감고 손으로 만지며 「찌르는 곳·판판한 곳·미끄러지는 곳」을 말로 나누게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X07','math',1,'u2',ARRAY['M1-1-u2-C3','M1-1-u2-C4']::text[],'기둥은 놓는 방향에 따라 다르다는 것을 모른다 — 세운 기둥도 굴러간다·눕힌 기둥도 잘 쌓인다고 함','같은 기둥을 세워서 한 번, 눕혀서 한 번 밀어 보고 다른 점을 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X08','math',1,'u2',ARRAY['M1-1-u2-C3','M1-1-u2-C4']::text[],'상자·공의 쌓기와 굴리기를 거꾸로 안다 — 공을 쌓을 수 있다, 상자가 굴러간다고 함','공 두 개를 실제로 쌓아 보게 하고, 상자를 밀어 「미끄러진다 vs 굴러간다」를 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X09','math',1,'u2',ARRAY['M1-1-u2-C3','M1-1-u2-C4']::text[],'기둥과 공의 굴러가는 모습을 가르지 못한다 — 기둥도 여러 방향으로 굴러간다고 함','바닥에 눕힌 기둥과 공을 같은 쪽으로 밀어 굴러간 자국을 분필로 그려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X10','math',1,'u2',ARRAY['M1-1-u2-C4']::text[],'쓰임에 어울리는 모양을 특징을 생각하지 않고 고른다 — 바퀴에 상자, 앉는 자리에 공','「이 자리는 굴러가야 해? 멈춰 있어야 해?」 먼저 묻고 그 특징이 있는 모양을 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X11','math',1,'u2',ARRAY['M1-1-u2-C4']::text[],'만든 것에서 모양을 빠뜨리거나 두 번 센다 — 누운 기둥·작은 모양을 빼먹음','모양마다 색연필 색을 정해 센 것에 점을 찍으며 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X12','math',1,'u2',ARRAY['M1-1-u2-C5']::text[],'같은 점·다른 점을 모양이 아니라 색깔·크기·쓰임으로 말한다','「생김새로만 말해 보자 — 평평한 곳, 뾰족한 곳, 둥근 곳」 말틀을 칠판에 붙여 두기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-1-u2-X13','math',1,'u2',ARRAY['M1-1-u2-C5']::text[],'일부만 보거나 단서 하나만 듣고 서둘러 정한다 — 둥근 부분이 만져지면 바로 공이라고 함','단서를 하나씩 더해 가며 「아직 될 수 있는 모양」을 손가락으로 세게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#1','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',1,'mc','auto','주사위는 어떤 모양인가요?',ARRAY['M1-1-u2-X02']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"주사위는 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X02"},{"t":"공 모양","mis":"M1-1-u2-X02"}],"explanation":["주사위는 평평한 부분과 뾰족한 부분이 있어요.","그래서 상자 모양이에요.","물건 이름이 아니라 생김새를 보고 나눠요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#2','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',1,'mc','auto','두루마리 휴지는 어떤 모양인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X05']::text[],true,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"두루마리 휴지는 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X04"},{"t":"상자 모양","mis":"M1-1-u2-X05"}],"explanation":["위·아래는 평평하고 옆은 둥글어요.","그래서 기둥 모양이에요.","둥근 곳이 있다고 다 공 모양은 아니에요."],"asset":{"type":"solid_row","items":[{"icon":"🧻","name":"두루마리 휴지"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#3','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',1,'mc','auto','구슬은 어떤 모양인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X02']::text[],true,'{"seq":3,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"구슬은 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X04"},{"t":"상자 모양","mis":"M1-1-u2-X02"}],"explanation":["구슬은 어디를 보아도 둥글어요.","이름에 「공」이 없어도 공 모양이에요.","이름 말고 생김새를 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🔮","name":"구슬"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#4','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',1,'sa','auto','그림은 어떤 모양인가요? 「○○ 모양」으로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-1-u2-C1","difficulty":1,"kind":"sa","stem":"그림은 어떤 모양인가요? 「○○ 모양」으로 쓰세요.","answer":["기둥 모양","기둥"],"explanation":["위·아래가 평평하고 옆이 둥글어요.","기둥 모양이에요.","평평한 곳과 둥근 곳이 함께 있는지 보세요."],"asset":{"type":"solid_row","items":["cyl"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림은 어떤 모양인가요? 「○○ 모양」으로 쓰세요.","answer":["상자 모양","상자"],"explanation":["평평한 부분과 뾰족한 부분이 있어요.","상자 모양이에요.","모서리 끝을 짚어 보세요."],"asset":{"type":"solid_row","items":["box"]}},{"stem":"이번에는 다른 보기예요. 그림은 어떤 모양인가요? 「○○ 모양」으로 쓰세요.","answer":["공 모양","공"],"explanation":["어디를 보아도 둥글어요.","공 모양이에요.","평평한 곳이 하나도 없어요."],"asset":{"type":"solid_row","items":["ball"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#5','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',2,'match','auto','물건과 같은 모양을 줄로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u2-C1","difficulty":2,"kind":"match","stem":"물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"택배 상자","r":"상자 모양"},{"l":"통조림","r":"기둥 모양"},{"l":"농구공","r":"공 모양"}],"mis":"M1-1-u2-X02","explanation":["택배 상자는 상자, 통조림은 기둥, 농구공은 공 모양이에요.","물건마다 평평한 곳·둥근 곳을 살펴요.","헷갈리면 그 물건을 손에 쥐었다고 떠올려 보세요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"도시락","r":"상자 모양"},{"l":"북","r":"기둥 모양"},{"l":"테니스공","r":"공 모양"}],"explanation":["도시락은 상자, 북은 기둥, 테니스공은 공 모양이에요.","물건마다 평평한 곳·둥근 곳을 살펴요.","쓰임이 아니라 생김새로 이어요."],"asset":null},{"stem":"이번에는 다른 보기예요. 물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"벽돌","r":"상자 모양"},{"l":"건전지","r":"기둥 모양"},{"l":"수박","r":"공 모양"}],"explanation":["벽돌은 상자, 건전지는 기둥, 수박은 공 모양이에요.","수박은 이름에 「공」이 없어도 공 모양이에요.","쓰임이 아니라 생김새로 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#6','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',2,'mc','auto','공 모양인 물건은 몇 개인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X11']::text[],true,'{"seq":6,"concept":"M1-1-u2-C1","difficulty":2,"kind":"mc","stem":"공 모양인 물건은 몇 개인가요?","options":[{"t":"2","correct":true},{"t":"3","mis":"M1-1-u2-X04"},{"t":"6","mis":"M1-1-u2-X11"}],"explanation":["공 모양은 축구공·구슬이에요.","모두 2개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"⚽","name":"축구공"},{"icon":"🥫","name":"통조림"},{"icon":"🎁","name":"선물 상자"},{"icon":"🔮","name":"구슬"},{"icon":"🧻","name":"두루마리 휴지"},{"icon":"🧊","name":"얼음"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#7','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',2,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X02']::text[],true,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":2,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"북","correct":true},{"t":"주사위","mis":"M1-1-u2-X01"},{"t":"도시락","mis":"M1-1-u2-X02"}],"explanation":["주사위·도시락·벽돌은 상자 모양이에요.","북만 기둥 모양이에요.","크기나 쓰임이 아니라 생김새를 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"},{"icon":"🥁","name":"북"},{"icon":"🍱","name":"도시락"},{"icon":"🧱","name":"벽돌"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#8','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',2,'ox','auto','크기가 다른 주사위와 택배 상자는 서로 다른 모양이에요.',ARRAY['M1-1-u2-X01']::text[],true,'{"seq":8,"concept":"M1-1-u2-C1","difficulty":2,"kind":"ox","stem":"크기가 다른 주사위와 택배 상자는 서로 다른 모양이에요.","answer":"X","reason_options":[{"t":"크기는 달라도 둘 다 평평한 부분과 뾰족한 부분이 있는 상자 모양이니까","correct":true},{"t":"크기가 다르면 모양도 다르니까","mis":"M1-1-u2-X01"}],"mis":"M1-1-u2-X01","explanation":["주사위도 택배 상자도 상자 모양이에요.","크기는 모양을 가르는 기준이 아니에요.","평평한 곳·뾰족한 곳이 같은지 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"},{"icon":"📦","name":"택배 상자"}]},"variant_rule":{"alt":[{"stem":"크기가 아주 다른 축구공과 구슬은 같은 모양이에요.","answer":"O","reason_options":[{"t":"크기는 달라도 둘 다 둥근 부분만 있는 공 모양이니까","correct":true},{"t":"크기가 다르면 모양도 다르니까","mis":"M1-1-u2-X01"}],"explanation":["축구공도 구슬도 공 모양이에요.","크기는 모양을 가르는 기준이 아니에요.","둥근 곳만 있는지 보세요."],"asset":{"type":"solid_row","items":[{"icon":"⚽","name":"축구공"},{"icon":"🔮","name":"구슬"}]}},{"stem":"색깔이 다른 통조림과 북은 서로 다른 모양이에요.","answer":"X","reason_options":[{"t":"색깔은 달라도 둘 다 위·아래가 평평하고 옆이 둥근 기둥 모양이니까","correct":true},{"t":"색깔이 다르면 모양도 다르니까","mis":"M1-1-u2-X01"}],"explanation":["통조림도 북도 기둥 모양이에요.","색깔은 모양을 가르는 기준이 아니에요.","평평한 곳과 둥근 곳을 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🥫","name":"통조림"},{"icon":"🥁","name":"북"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#9','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',2,'blank','auto','축구공, 구슬, 수박은 모두 (        ) 모양이에요.',ARRAY['M1-1-u2-X04','M1-1-u2-X02']::text[],true,'{"seq":9,"concept":"M1-1-u2-C1","difficulty":2,"kind":"blank","stem":"축구공, 구슬, 수박은 모두 (        ) 모양이에요.","options":[{"t":"공","correct":true},{"t":"기둥","mis":"M1-1-u2-X04"},{"t":"상자","mis":"M1-1-u2-X02"}],"explanation":["셋 다 어디를 보아도 둥글어요.","모두 공 모양이에요.","이름에 「공」이 없어도 생김새가 같으면 같은 모양이에요."],"variant_rule":{"alt":[{"stem":"주사위, 벽돌, 선물 상자는 모두 (        ) 모양이에요.","options":[{"t":"상자","correct":true},{"t":"기둥","mis":"M1-1-u2-X05"},{"t":"공","mis":"M1-1-u2-X02"}],"explanation":["셋 다 평평한 부분과 뾰족한 부분이 있어요.","모두 상자 모양이에요.","크기가 달라도 같은 모양이에요."],"asset":null},{"stem":"통조림, 북, 두루마리 휴지는 모두 (        ) 모양이에요.","options":[{"t":"기둥","correct":true},{"t":"공","mis":"M1-1-u2-X04"},{"t":"상자","mis":"M1-1-u2-X05"}],"explanation":["셋 다 위·아래가 평평하고 옆이 둥글어요.","모두 기둥 모양이에요.","둥근 곳이 있다고 다 공 모양은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_basic#10','math',1,1,'u2','L02','g1_1_math_u2_L02_basic','lesson_basic','M1-1-u2-C1',3,'error','auto','하람이가 물건을 모양대로 나누었어요. 잘못 나눈 것은 어느 것인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X02']::text[],true,'{"seq":10,"concept":"M1-1-u2-C1","difficulty":3,"kind":"error","stem":"하람이가 물건을 모양대로 나누었어요. 잘못 나눈 것은 어느 것인가요?","options":[{"t":"건전지 — 공 모양","correct":true,"mis_target":"M1-1-u2-X04"},{"t":"얼음 — 상자 모양","mis":"M1-1-u2-X02"},{"t":"북 — 기둥 모양","mis":"M1-1-u2-X02"}],"explanation":["건전지는 위·아래가 평평하고 옆이 둥근 기둥 모양이에요.","둥근 곳만 보고 공 모양이라고 했어요.","평평한 곳이 있는지도 꼭 보세요."],"variant_rule":{"alt":[{"stem":"지호가 물건을 모양대로 나누었어요. 잘못 나눈 것은 어느 것인가요?","options":[{"t":"통조림 — 상자 모양","correct":true,"mis_target":"M1-1-u2-X05"},{"t":"테니스공 — 공 모양","mis":"M1-1-u2-X02"},{"t":"도시락 — 상자 모양","mis":"M1-1-u2-X02"}],"explanation":["통조림은 옆이 둥근 기둥 모양이에요.","평평한 위·아래만 보고 상자 모양이라고 했어요.","옆에 둥근 곳이 있는지도 보세요."],"asset":null},{"stem":"나린이가 물건을 모양대로 나누었어요. 잘못 나눈 것은 어느 것인가요?","options":[{"t":"수박 — 기둥 모양","correct":true,"mis_target":"M1-1-u2-X02"},{"t":"벽돌 — 상자 모양","mis":"M1-1-u2-X02"},{"t":"두루마리 휴지 — 기둥 모양","mis":"M1-1-u2-X02"}],"explanation":["수박은 어디를 보아도 둥근 공 모양이에요.","「공」이라는 이름이 없다고 공 모양이 아닌 게 아니에요.","이름 말고 생김새를 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#1','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',2,'ox','auto','통조림은 공 모양이에요.',ARRAY['M1-1-u2-X04']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":2,"kind":"ox","stem":"통조림은 공 모양이에요.","answer":"X","reason_options":[{"t":"평평한 부분과 둥근 부분이 있는 기둥 모양이니까","correct":true},{"t":"크기와 색깔을 보면 모양을 알 수 있으니까","mis":"M1-1-u2-X04"}],"mis":"M1-1-u2-X04","explanation":["통조림은 기둥 모양이에요.","공 모양이 아니에요 — 위·아래가 평평해요.","평평한 곳·뾰족한 곳·둥근 곳이 있는지 차례로 살펴요."],"asset":{"type":"solid_row","items":[{"icon":"🥫","name":"통조림"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#2','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',2,'sa','auto','상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":2,"kind":"sa","stem":"상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["상자 모양은 선물 상자·벽돌·도시락이에요.","모두 3개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🎁","name":"선물 상자"},{"icon":"🏀","name":"농구공"},{"icon":"🧱","name":"벽돌"},{"icon":"🔋","name":"건전지"},{"icon":"🍱","name":"도시락"},{"icon":"🎾","name":"테니스공"}]},"variant_rule":{"solids":{"ask":"count","len":[6,7]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#3','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',3,'mc','auto','두 그림은 놓인 모습이 달라요. 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X03']::text[],true,'{"seq":3,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"두 그림은 놓인 모습이 달라요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"누운 것은 상자 모양이에요","mis":"M1-1-u2-X03"},{"t":"누운 것은 공 모양이에요","mis":"M1-1-u2-X03"}],"explanation":["누워 있어도 위·아래는 평평하고 옆은 둥글어요.","놓인 방향이 바뀌어도 모양은 그대로예요.","머릿속으로 누운 것을 일으켜 세워 보세요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true},"variant_rule":{"alt":[{"stem":"건전지는 누워 있고 통조림은 서 있어요. 두 물건의 모양을 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"건전지는 누워 있으니 상자 모양이에요","mis":"M1-1-u2-X03"},{"t":"건전지는 공 모양, 통조림은 기둥 모양이에요","mis":"M1-1-u2-X04"}],"explanation":["건전지도 통조림도 평평한 위·아래와 둥근 옆이 있어요.","누워 있어도 기둥 모양이에요.","방향은 모양을 가르는 기준이 아니에요."],"asset":{"type":"solid_row","items":[{"icon":"🔋","name":"건전지"},{"icon":"🥫","name":"통조림"}]}},{"stem":"통나무가 바닥에 누워 있어요. 통나무는 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X03"},{"t":"공 모양","mis":"M1-1-u2-X04"}],"explanation":["통나무는 양 끝이 평평하고 옆이 둥글어요.","누워 있어도 기둥 모양이에요.","세워 놓았다고 생각해 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🪵","name":"통나무"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#4','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',3,'error','auto','두 필통을 본뜬 모양이에요. 지우가 한 말 가운데 틀린 것은 어느 것인가요?',ARRAY['M1-1-u2-X02','M1-1-u2-X06']::text[],true,'{"seq":4,"concept":"M1-1-u2-C1","difficulty":3,"kind":"error","stem":"두 필통을 본뜬 모양이에요. 지우가 한 말 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「필통은 모두 상자 모양이야.」","correct":true,"mis_target":"M1-1-u2-X02"},{"t":"「①은 뾰족한 부분이 있어.」","mis":"M1-1-u2-X06"},{"t":"「②는 옆이 둥글어.」","mis":"M1-1-u2-X06"}],"explanation":["①은 상자 모양, ②는 기둥 모양이에요.","같은 필통이라도 생김새가 다르면 모양이 달라요.","이름이 아니라 생김새로 나눠요."],"asset":{"type":"solid_row","items":["box","cyl"],"num":true},"variant_rule":{"alt":[{"stem":"두 쓰레기통을 본뜬 모양이에요. 서아가 한 말 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「쓰레기통은 모두 기둥 모양이야.」","correct":true,"mis_target":"M1-1-u2-X02"},{"t":"「①은 옆이 둥글어.」","mis":"M1-1-u2-X06"},{"t":"「②는 뾰족한 부분이 있어.」","mis":"M1-1-u2-X06"}],"explanation":["①은 기둥 모양, ②는 상자 모양이에요.","같은 쓰레기통이라도 생김새가 다르면 모양이 달라요.","이름이 아니라 생김새로 나눠요."],"asset":{"type":"solid_row","items":["cyl","box"],"num":true}},{"stem":"두 저금통을 본뜬 모양이에요. 도윤이가 한 말 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「저금통은 모두 같은 모양이야.」","correct":true,"mis_target":"M1-1-u2-X02"},{"t":"「①은 어디를 보아도 둥글어.」","mis":"M1-1-u2-X06"},{"t":"「②는 위·아래가 평평해.」","mis":"M1-1-u2-X06"}],"explanation":["①은 공 모양, ②는 기둥 모양이에요.","같은 저금통이라도 생김새가 다르면 모양이 달라요.","이름이 아니라 생김새로 나눠요."],"asset":{"type":"solid_row","items":["ball","cyl"],"num":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#5','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',3,'mc','auto','공 모양이 아닌 것은 어느 것인가요?',ARRAY['M1-1-u2-X02']::text[],true,'{"seq":5,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"공 모양이 아닌 것은 어느 것인가요?","options":[{"t":"두루마리 휴지","correct":true},{"t":"구슬","mis":"M1-1-u2-X02"},{"t":"수박","mis":"M1-1-u2-X02"}],"explanation":["두루마리 휴지는 기둥 모양이에요.","구슬·수박은 이름에 「공」이 없어도 공 모양이에요.","이름이 아니라 생김새로 골라요."],"variant_rule":{"alt":[{"stem":"상자 모양이 아닌 것은 어느 것인가요?","options":[{"t":"북","correct":true},{"t":"얼음","mis":"M1-1-u2-X02"},{"t":"도시락","mis":"M1-1-u2-X02"}],"explanation":["북은 기둥 모양이에요.","얼음·도시락은 상자 모양이에요.","평평한 곳과 뾰족한 곳이 다 있는지 보세요."],"asset":null},{"stem":"기둥 모양이 아닌 것은 어느 것인가요?","options":[{"t":"당구공","correct":true},{"t":"건전지","mis":"M1-1-u2-X03"},{"t":"통나무","mis":"M1-1-u2-X03"}],"explanation":["당구공은 공 모양이에요.","건전지·통나무는 누워 있어도 기둥 모양이에요.","평평한 곳이 있는지 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#6','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',3,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X04']::text[],true,'{"seq":6,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"축구공","correct":true},{"t":"통조림","mis":"M1-1-u2-X04"},{"t":"북","mis":"M1-1-u2-X04"}],"explanation":["통조림·북·건전지는 기둥 모양이에요.","축구공만 공 모양이에요.","둥근 곳만 있는지, 평평한 곳도 있는지 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🥫","name":"통조림"},{"icon":"🥁","name":"북"},{"icon":"⚽","name":"축구공"},{"icon":"🔋","name":"건전지"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#7','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',3,'ox','auto','같은 기둥 모양 물건이라도 색깔과 크기는 다를 수 있어요.',ARRAY['M1-1-u2-X01']::text[],true,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":3,"kind":"ox","stem":"같은 기둥 모양 물건이라도 색깔과 크기는 다를 수 있어요.","answer":"O","reason_options":[{"t":"모양은 생김새로 나누고 색깔·크기는 따지지 않으니까","correct":true},{"t":"같은 모양이면 색깔과 크기도 같아야 하니까","mis":"M1-1-u2-X01"}],"mis":"M1-1-u2-X01","explanation":["큰 통나무와 작은 건전지는 둘 다 기둥 모양이에요.","색깔·크기가 달라도 같은 모양일 수 있어요.","생김새만 견주어요."],"variant_rule":{"alt":[{"stem":"같은 공 모양 물건은 크기도 모두 같아요.","answer":"X","reason_options":[{"t":"모양은 생김새로 나누니 크기는 달라도 되니까","correct":true},{"t":"같은 모양이면 크기도 같아야 하니까","mis":"M1-1-u2-X01"}],"explanation":["구슬과 수박은 크기가 달라도 공 모양이에요.","크기는 모양을 가르는 기준이 아니에요.","생김새만 견주어요."],"asset":null},{"stem":"같은 상자 모양 물건이라도 쓰임은 다를 수 있어요.","answer":"O","reason_options":[{"t":"모양은 생김새로 나누고 쓰임은 따지지 않으니까","correct":true},{"t":"같은 모양이면 쓰임도 같아야 하니까","mis":"M1-1-u2-X02"}],"explanation":["주사위는 놀이에, 도시락은 밥 담는 데 써요.","쓰임이 달라도 둘 다 상자 모양이에요.","생김새만 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#8','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',4,'sa','auto','기둥 모양은 모두 몇 개인가요? 누워 있는 것도 잘 보고 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u2-C1","difficulty":4,"kind":"sa","stem":"기둥 모양은 모두 몇 개인가요? 누워 있는 것도 잘 보고 숫자로 쓰세요.","answer":["4"],"explanation":["선 기둥·누운 기둥·통조림·건전지가 기둥 모양이에요.","모두 4개예요 — 누운 것도 기둥이에요.","평평한 곳과 둥근 곳이 함께 있는 것을 찾아요."],"asset":{"type":"solid_row","items":["cyl_lay",{"icon":"🥫","name":"통조림"},"box",{"icon":"🔋","name":"건전지"},"ball","cyl"]},"variant_rule":{"alt":[{"stem":"상자 모양은 모두 몇 개인가요? 크기가 달라도 잘 보고 숫자로 쓰세요.","answer":["3"],"explanation":["그림 상자·주사위·택배 상자가 상자 모양이에요.","모두 3개예요 — 크기는 상관없어요.","평평한 곳과 뾰족한 곳이 있는 것을 찾아요."],"asset":{"type":"solid_row","items":["box",{"icon":"🎲","name":"주사위"},"cyl_lay",{"icon":"📦","name":"택배 상자"},"ball",{"icon":"🥁","name":"북"}]}},{"stem":"공 모양은 모두 몇 개인가요? 이름에 「공」이 없는 것도 잘 보고 숫자로 쓰세요.","answer":["3"],"explanation":["그림 공·구슬·배구공이 공 모양이에요.","모두 3개예요 — 구슬도 공 모양이에요.","둥근 곳만 있는 것을 찾아요."],"asset":{"type":"solid_row","items":["ball","cyl_lay",{"icon":"🔮","name":"구슬"},{"icon":"🧻","name":"두루마리 휴지"},{"icon":"🏐","name":"배구공"},"box"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#9','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',4,'essay','teacher','축구공과 구슬은 크기가 아주 달라요. 그래도 같은 모양이라고 할 수 있는 까닭을 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"M1-1-u2-C1","difficulty":4,"kind":"essay","stem":"축구공과 구슬은 크기가 아주 달라요. 그래도 같은 모양이라고 할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 둘 다 어디를 보아도 둥글고 평평한 곳이 없어서 둘 다 공 모양이에요. 크기는 달라도 생김새가 같으니까 같은 모양이에요.","scoring_points":["둘 다 공 모양이라고 했는가","「둥글다·평평한 곳이 없다」처럼 생김새로 까닭을 댔는가","크기는 모양을 가르는 기준이 아님을 말했는가"]},"explanation":["모양은 생김새로 가려요.","둘 다 둥근 곳만 있어요.","크기는 따지지 않아요."],"variant_rule":{"alt":[{"stem":"주사위와 택배 상자는 크기가 아주 달라요. 그래도 같은 모양이라고 할 수 있는 까닭을 써 보세요.","answer_guide":{"answer":"예: 둘 다 평평한 부분과 뾰족한 부분이 있어서 상자 모양이에요. 크기만 다르고 생김새는 같아요.","scoring_points":["둘 다 상자 모양이라고 했는가","「평평한 곳·뾰족한 곳」처럼 생김새로 까닭을 댔는가","크기는 모양을 가르는 기준이 아님을 말했는가"]},"explanation":["모양은 생김새로 가려요.","둘 다 평평한 곳과 뾰족한 곳이 있어요.","크기는 따지지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L02_challenge#10','math',1,1,'u2','L02','g1_1_math_u2_L02_challenge','lesson_challenge','M1-1-u2-C1',4,'mc','auto','세 물건씩 같은 모양끼리 묶었어요. 바르게 묶은 것은 어느 것인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X04']::text[],true,'{"seq":10,"concept":"M1-1-u2-C1","difficulty":4,"kind":"mc","stem":"세 물건씩 같은 모양끼리 묶었어요. 바르게 묶은 것은 어느 것인가요?","options":[{"t":"통조림 · 북 · 두루마리 휴지","correct":true},{"t":"통조림 · 주사위 · 북","mis":"M1-1-u2-X05"},{"t":"구슬 · 북 · 농구공","mis":"M1-1-u2-X04"}],"explanation":["통조림·북·두루마리 휴지는 모두 기둥 모양이에요.","주사위는 상자, 구슬·농구공은 공 모양이라 섞였어요.","한 물건씩 모양을 먼저 정하고 묶어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 세 물건씩 같은 모양끼리 묶었어요. 바르게 묶은 것은 어느 것인가요?","options":[{"t":"구슬 · 수박 · 테니스공","correct":true},{"t":"구슬 · 건전지 · 테니스공","mis":"M1-1-u2-X04"},{"t":"수박 · 도시락 · 구슬","mis":"M1-1-u2-X02"}],"explanation":["구슬·수박·테니스공은 모두 공 모양이에요.","건전지는 기둥, 도시락은 상자 모양이라 섞였어요.","한 물건씩 모양을 먼저 정하고 묶어요."],"asset":null},{"stem":"이번에는 다른 보기예요. 세 물건씩 같은 모양끼리 묶었어요. 바르게 묶은 것은 어느 것인가요?","options":[{"t":"얼음 · 벽돌 · 선물 상자","correct":true},{"t":"얼음 · 통조림 · 벽돌","mis":"M1-1-u2-X05"},{"t":"선물 상자 · 배구공 · 도시락","mis":"M1-1-u2-X02"}],"explanation":["얼음·벽돌·선물 상자는 모두 상자 모양이에요.","통조림은 기둥, 배구공은 공 모양이라 섞였어요.","한 물건씩 모양을 먼저 정하고 묶어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#1','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C2',1,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#2','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C2',1,'ox','auto','공 모양은 평평한 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":2,"concept":"M1-1-u2-C2","difficulty":1,"kind":"ox","stem":"공 모양은 평평한 부분이 있어요.","answer":"X","reason_options":[{"t":"어디를 만져도 둥글기만 하니까","correct":true},{"t":"위와 아래가 평평하니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["공 모양은 평평한 부분이 없어요.","위와 아래가 평평한 것은 기둥 모양이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["flat","corner","round"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#3','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C2',1,'match','auto','모양과 그 모양에 있는 부분을 줄로 이어 보세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u2-C2","difficulty":1,"kind":"match","stem":"모양과 그 모양에 있는 부분을 줄로 이어 보세요.","pairs":[{"l":"상자 모양","r":"평평한 부분과 뾰족한 부분"},{"l":"기둥 모양","r":"평평한 부분과 둥근 부분"},{"l":"공 모양","r":"둥근 부분만"}],"mis":"M1-1-u2-X06","explanation":["상자는 평평·뾰족, 기둥은 평평·둥근, 공은 둥근 부분만 있어요.","기둥에는 뾰족한 곳이 없어요.","손으로 만진다고 떠올리며 이어요."],"variant_rule":{"alt":[{"stem":"설명과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"뾰족한 곳이 만져져요","r":"상자 모양"},{"l":"위·아래는 평평하고 옆은 둥글어요","r":"기둥 모양"},{"l":"평평한 곳이 하나도 없어요","r":"공 모양"}],"explanation":["뾰족한 곳은 상자에만 있어요.","평평한 곳과 둥근 곳이 함께 있으면 기둥이에요.","평평한 곳이 없으면 공이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#4','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C2',1,'mc','auto','그림의 모양에서 평평한 부분은 어디인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X06']::text[],true,'{"seq":4,"concept":"M1-1-u2-C2","difficulty":1,"kind":"mc","stem":"그림의 모양에서 평평한 부분은 어디인가요?","options":[{"t":"위와 아래","correct":true},{"t":"둥근 옆","mis":"M1-1-u2-X05"},{"t":"평평한 부분이 없어요","mis":"M1-1-u2-X06"}],"explanation":["기둥 모양은 위와 아래가 평평해요.","옆은 둥근 부분이에요.","손바닥을 대면 판판한 곳이 평평한 부분이에요."],"asset":{"type":"solid_row","items":["cyl"]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림의 모양에서 평평한 부분은 어디인가요?","options":[{"t":"평평한 부분이 없어요","correct":true},{"t":"위와 아래","mis":"M1-1-u2-X06"},{"t":"옆","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 어디를 만져도 둥글어요.","평평한 부분이 하나도 없어요.","손바닥을 대 보면 판판한 곳이 없어요."],"asset":{"type":"solid_row","items":["ball"]}},{"stem":"그림의 모양에 있는 부분을 바르게 말한 것은 어느 것인가요?","options":[{"t":"평평한 부분과 뾰족한 부분","correct":true},{"t":"평평한 부분과 둥근 부분","mis":"M1-1-u2-X04"},{"t":"둥근 부분만","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 평평한 부분과 뾰족한 부분이 있어요.","둥근 부분은 없어요.","모서리 끝을 짚어 보세요."],"asset":{"type":"solid_row","items":["box"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#5','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C2',2,'blank','auto','기둥 모양은 위와 아래가 (        ) 옆은 둥글어요.',ARRAY['M1-1-u2-X06','M1-1-u2-X04']::text[],true,'{"seq":5,"concept":"M1-1-u2-C2","difficulty":2,"kind":"blank","stem":"기둥 모양은 위와 아래가 (        ) 옆은 둥글어요.","options":[{"t":"평평하고","correct":true},{"t":"뾰족하고","mis":"M1-1-u2-X06"},{"t":"둥글고","mis":"M1-1-u2-X04"}],"explanation":["기둥 모양의 위와 아래는 평평해요.","뾰족한 곳은 없고, 둥근 곳은 옆이에요.","휴지 심을 떠올려 보세요."],"variant_rule":{"alt":[{"stem":"상자 모양은 평평한 부분이 있고 (        ) 부분도 있어요.","options":[{"t":"뾰족한","correct":true},{"t":"둥근","mis":"M1-1-u2-X04"},{"t":"없는","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 모서리 끝이 뾰족해요.","둥근 부분은 없어요.","주사위 모서리를 떠올려 보세요."],"asset":null},{"stem":"공 모양은 (        ) 부분만 있어요.","options":[{"t":"둥근","correct":true},{"t":"평평한","mis":"M1-1-u2-X06"},{"t":"뾰족한","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 어디를 만져도 둥글어요.","평평한 곳도 뾰족한 곳도 없어요.","구슬을 떠올려 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#6','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C3',2,'ox','auto','상자 모양은 여러 방향으로 잘 굴러가요.',ARRAY['M1-1-u2-X08']::text[],true,'{"seq":6,"concept":"M1-1-u2-C3","difficulty":2,"kind":"ox","stem":"상자 모양은 여러 방향으로 잘 굴러가요.","answer":"X","reason_options":[{"t":"평평해서 굴러가지 않으니까","correct":true},{"t":"어느 쪽으로 밀어도 둥근 부분이 바닥에 닿으니까","mis":"M1-1-u2-X08"}],"mis":"M1-1-u2-X08","explanation":["상자 모양은 여러 방향으로 굴러가지 않아요.","「여러 방향으로 잘 굴러가요」는 공 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["rollall","stack"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#7','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C3',2,'mc','auto','공 모양은 어떻게 굴러가나요?',ARRAY['M1-1-u2-X09','M1-1-u2-X08']::text[],true,'{"seq":7,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"공 모양은 어떻게 굴러가나요?","options":[{"t":"여러 방향으로 잘 굴러가요","correct":true},{"t":"한 방향으로만 굴러가요","mis":"M1-1-u2-X09"},{"t":"굴러가지 않아요","mis":"M1-1-u2-X08"}],"explanation":["공 모양은 어느 쪽으로 밀어도 둥근 부분이 바닥에 닿아요.","그래서 여러 방향으로 잘 굴러가요.","한 방향으로만 굴러가는 것은 눕힌 기둥이에요."],"variant_rule":{"alt":[{"stem":"상자 모양을 밀면 어떻게 되나요?","options":[{"t":"굴러가지 않아요","correct":true},{"t":"여러 방향으로 잘 굴러가요","mis":"M1-1-u2-X08"},{"t":"한 방향으로만 굴러가요","mis":"M1-1-u2-X07"}],"explanation":["상자 모양은 평평한 부분이 바닥에 닿아요.","그래서 굴러가지 않아요.","밀면 미끄러질 뿐이에요."],"asset":null},{"stem":"눕힌 기둥 모양을 밀면 어떻게 굴러가나요?","options":[{"t":"한 방향으로 굴러가요","correct":true},{"t":"여러 방향으로 굴러가요","mis":"M1-1-u2-X09"},{"t":"굴러가지 않아요","mis":"M1-1-u2-X07"}],"explanation":["눕힌 기둥은 둥근 옆이 바닥에 닿아요.","그래서 한 방향으로 굴러가요.","여러 방향으로 굴러가는 것은 공 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#8','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C3',2,'mc','auto','두 기둥을 밀었어요. 굴러가는 것은 어느 것인가요?',ARRAY['M1-1-u2-X07']::text[],true,'{"seq":8,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"두 기둥을 밀었어요. 굴러가는 것은 어느 것인가요?","options":[{"t":"② 누운 기둥","correct":true},{"t":"① 선 기둥","mis":"M1-1-u2-X07"},{"t":"둘 다 잘 굴러가요","mis":"M1-1-u2-X07"}],"explanation":["누운 기둥은 둥근 옆이 바닥에 닿아 굴러가요.","선 기둥은 평평한 아래가 바닥에 닿아 굴러가지 않아요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true},"variant_rule":{"alt":[{"stem":"두 기둥 위에 책을 올려 쌓으려고 해요. 쌓기 좋은 것은 어느 것인가요?","options":[{"t":"① 선 기둥","correct":true},{"t":"② 누운 기둥","mis":"M1-1-u2-X07"},{"t":"둘 다 쌓을 수 없어요","mis":"M1-1-u2-X07"}],"explanation":["선 기둥은 평평한 위에 올릴 수 있어요.","누운 기둥은 둥근 옆 때문에 굴러떨어져요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#9','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C3',2,'sa','auto','쌓을 수 없는 모양은 무엇인가요? 「○○ 모양」으로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M1-1-u2-C3","difficulty":2,"kind":"sa","stem":"쌓을 수 없는 모양은 무엇인가요? 「○○ 모양」으로 쓰세요.","answer":["공 모양","공"],"explanation":["공 모양은 평평한 부분이 없어요.","위에 올리면 굴러떨어져서 쌓을 수 없어요.","상자와 세운 기둥은 쌓을 수 있어요."],"variant_rule":{"alt":[{"stem":"밀어도 굴러가지 않는 모양은 무엇인가요? 「○○ 모양」으로 쓰세요.","answer":["상자 모양","상자"],"explanation":["상자 모양은 평평한 부분만 바닥에 닿아요.","그래서 굴러가지 않아요.","기둥은 눕히면 굴러가요."],"asset":null},{"stem":"세우면 쌓을 수 있고 눕히면 굴러가는 모양은 무엇인가요? 「○○ 모양」으로 쓰세요.","answer":["기둥 모양","기둥"],"explanation":["세우면 평평한 부분끼리 맞닿아 쌓여요.","눕히면 둥근 옆으로 굴러가요.","두 가지를 다 하는 것은 기둥 모양뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_basic#10','math',1,1,'u2','L03','g1_1_math_u2_L03_basic','lesson_basic','M1-1-u2-C3',3,'error','auto','친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X08']::text[],true,'{"seq":10,"concept":"M1-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"시우: 「기둥 모양은 어떻게 놓아도 잘 굴러가.」","correct":true,"mis_target":"M1-1-u2-X07"},{"t":"하윤: 「공 모양은 어느 쪽으로든 굴러가.」","mis":"M1-1-u2-X08"},{"t":"도겸: 「상자 모양은 밀어도 굴러가지 않아.」","mis":"M1-1-u2-X08"}],"explanation":["기둥 모양은 세워 두면 굴러가지 않아요.","눕혀야 한 방향으로 굴러가요.","놓는 방향을 바꿔 가며 생각해 보세요."],"variant_rule":{"alt":[{"stem":"친구들이 모양을 쌓아 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"하윤: 「공 모양도 조심하면 높이 쌓을 수 있어.」","correct":true,"mis_target":"M1-1-u2-X08"},{"t":"시우: 「상자 모양은 잘 쌓여.」","mis":"M1-1-u2-X08"},{"t":"도겸: 「기둥 모양은 세우면 쌓을 수 있어.」","mis":"M1-1-u2-X07"}],"explanation":["공 모양은 평평한 부분이 없어요.","위에 올리면 굴러떨어져서 쌓을 수 없어요.","평평한 곳끼리 맞닿아야 쌓여요."],"asset":null},{"stem":"이번에는 다른 보기예요. 친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"도겸: 「눕힌 기둥도 공처럼 여러 방향으로 굴러가.」","correct":true,"mis_target":"M1-1-u2-X09"},{"t":"하윤: 「공 모양은 여러 방향으로 굴러가.」","mis":"M1-1-u2-X08"},{"t":"시우: 「상자 모양은 굴러가지 않아.」","mis":"M1-1-u2-X08"}],"explanation":["눕힌 기둥은 한 방향으로만 굴러가요.","여러 방향으로 굴러가는 것은 공 모양이에요.","굴러간 자국을 떠올려 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#1','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C2',2,'ox','auto','기둥 모양은 뾰족한 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":1,"concept":"M1-1-u2-C2","difficulty":2,"kind":"ox","stem":"기둥 모양은 뾰족한 부분이 있어요.","answer":"X","reason_options":[{"t":"평평한 부분과 둥근 부분만 있으니까","correct":true},{"t":"모서리 끝이 뾰족하니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["기둥 모양은 뾰족한 부분이 없어요.","「뾰족한 부분이 있어요」는 상자 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#2','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C2',2,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#3','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C2',3,'mc','auto','평평한 부분도 있고 둥근 부분도 있는 물건은 어느 것인가요?',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":3,"concept":"M1-1-u2-C2","difficulty":3,"kind":"mc","stem":"평평한 부분도 있고 둥근 부분도 있는 물건은 어느 것인가요?","options":[{"t":"통조림","correct":true},{"t":"주사위","mis":"M1-1-u2-X06"},{"t":"구슬","mis":"M1-1-u2-X06"}],"explanation":["통조림은 위·아래가 평평하고 옆이 둥글어요.","주사위는 둥근 곳이 없고, 구슬은 평평한 곳이 없어요.","두 부분이 함께 있는지 하나씩 확인해요."],"variant_rule":{"alt":[{"stem":"뾰족한 부분이 있는 물건은 어느 것인가요?","options":[{"t":"벽돌","correct":true},{"t":"북","mis":"M1-1-u2-X06"},{"t":"테니스공","mis":"M1-1-u2-X06"}],"explanation":["벽돌은 상자 모양이라 모서리 끝이 뾰족해요.","북과 테니스공에는 뾰족한 곳이 없어요.","모서리 끝을 짚어 보세요."],"asset":null},{"stem":"평평한 부분이 하나도 없는 물건은 어느 것인가요?","options":[{"t":"배구공","correct":true},{"t":"건전지","mis":"M1-1-u2-X05"},{"t":"도시락","mis":"M1-1-u2-X06"}],"explanation":["배구공은 어디를 만져도 둥글어요.","건전지는 양 끝, 도시락은 모든 면이 평평해요.","손바닥을 대 보면 판판한 곳이 있는지 알아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#4','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C2',3,'error','auto','주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?',ARRAY['M1-1-u2-X06','M1-1-u2-X04']::text[],true,'{"seq":4,"concept":"M1-1-u2-C2","difficulty":3,"kind":"error","stem":"주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「뾰족한 부분이 두 군데 있어요.」","correct":true,"mis_target":"M1-1-u2-X06"},{"t":"「위와 아래가 평평해요.」","mis":"M1-1-u2-X06"},{"t":"「옆이 둥글어요.」","mis":"M1-1-u2-X04"}],"explanation":["기둥 모양은 뾰족한 부분이 없어요.","위·아래는 평평하고 옆은 둥근 것이 맞아요.","테두리와 뾰족한 곳은 달라요 — 찔리는 곳이 있나 만져 보세요."],"variant_rule":{"alt":[{"stem":"주원이가 공 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「아래쪽이 조금 평평해요.」","correct":true,"mis_target":"M1-1-u2-X06"},{"t":"「둥근 부분만 있어요.」","mis":"M1-1-u2-X06"},{"t":"「뾰족한 부분이 없어요.」","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 평평한 곳이 하나도 없어요.","둥근 부분만 있고 뾰족한 곳도 없어요.","어디를 놓아도 굴러가는 까닭을 떠올려요."],"asset":null},{"stem":"주원이가 상자 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「옆이 둥글어요.」","correct":true,"mis_target":"M1-1-u2-X04"},{"t":"「평평한 부분이 있어요.」","mis":"M1-1-u2-X06"},{"t":"「뾰족한 부분이 있어요.」","mis":"M1-1-u2-X06"}],"explanation":["상자 모양에는 둥근 부분이 없어요.","평평한 부분과 뾰족한 부분만 있어요.","옆이 둥근 것은 기둥 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#5','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C3',3,'mc','auto','비탈길 위에 세 모양을 눕히거나 굴려 보았어요. 어떻게 놓아도 굴러 내려가지 않는 것은 어느 것인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X08']::text[],true,'{"seq":5,"concept":"M1-1-u2-C3","difficulty":3,"kind":"mc","stem":"비탈길 위에 세 모양을 눕히거나 굴려 보았어요. 어떻게 놓아도 굴러 내려가지 않는 것은 어느 것인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X07"},{"t":"공 모양","mis":"M1-1-u2-X08"}],"explanation":["상자 모양은 평평한 부분만 바닥에 닿아요.","기둥은 눕히면 굴러가고, 공은 늘 굴러가요.","바닥에 닿는 부분이 평평한지 둥근지 보세요."],"variant_rule":{"alt":[{"stem":"비탈길 위에 세 모양을 놓았어요. 어떻게 놓아도 굴러 내려가는 것은 어느 것인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X07"},{"t":"상자 모양","mis":"M1-1-u2-X08"}],"explanation":["공 모양은 어느 쪽이든 둥근 부분이 바닥에 닿아요.","기둥은 세우면 멈추고, 상자는 굴러가지 않아요.","바닥에 닿는 부분을 생각해요."],"asset":null},{"stem":"비탈길 위에 세 모양을 놓았어요. 놓는 방향에 따라 굴러가기도 하고 멈추기도 하는 것은 어느 것인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X09"},{"t":"상자 모양","mis":"M1-1-u2-X08"}],"explanation":["기둥은 눕히면 굴러가고 세우면 멈춰요.","공은 늘 굴러가고, 상자는 늘 멈춰요.","세웠을 때와 눕혔을 때를 따로 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#6','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C3',3,'mc','auto','탑을 높이 쌓으려고 해요. 맨 아래에 놓기에 알맞지 않은 것은 어느 것인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X07']::text[],true,'{"seq":6,"concept":"M1-1-u2-C3","difficulty":3,"kind":"mc","stem":"탑을 높이 쌓으려고 해요. 맨 아래에 놓기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X08"},{"t":"세운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["공 모양은 평평한 부분이 없어 위에 올린 것이 굴러떨어져요.","상자와 세운 기둥은 위가 평평해 올릴 수 있어요.","위에 올릴 자리가 평평한지 보세요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 탑을 높이 쌓으려고 해요. 맨 아래에 놓기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"누운 기둥 모양","correct":true},{"t":"세운 기둥 모양","mis":"M1-1-u2-X07"},{"t":"상자 모양","mis":"M1-1-u2-X08"}],"explanation":["누운 기둥은 둥근 옆이 위로 와서 올린 것이 굴러떨어져요.","세운 기둥과 상자는 위가 평평해요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#7','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C3',3,'ox','auto','기둥 모양은 쌓을 수도 있고 굴릴 수도 있어요.',ARRAY['M1-1-u2-X07']::text[],true,'{"seq":7,"concept":"M1-1-u2-C3","difficulty":3,"kind":"ox","stem":"기둥 모양은 쌓을 수도 있고 굴릴 수도 있어요.","answer":"O","reason_options":[{"t":"세우면 쌓이고 눕히면 굴러가니까","correct":true},{"t":"기둥은 어떻게 놓아도 똑같으니까","mis":"M1-1-u2-X07"}],"mis":"M1-1-u2-X07","explanation":["기둥은 세우면 평평한 부분끼리 맞닿아 쌓여요.","눕히면 둥근 옆으로 굴러가요.","놓는 방향에 따라 둘 다 할 수 있어요."],"variant_rule":{"alt":[{"stem":"공 모양은 쌓을 수도 있고 굴릴 수도 있어요.","answer":"X","reason_options":[{"t":"평평한 부분이 없어 쌓으면 굴러떨어지니까","correct":true},{"t":"둥근 것끼리 붙여 놓으면 쌓이니까","mis":"M1-1-u2-X08"}],"explanation":["공 모양은 굴릴 수는 있지만 쌓을 수는 없어요.","평평한 부분이 없어요.","둘 다 할 수 있는 것은 기둥 모양이에요."],"asset":null},{"stem":"상자 모양은 쌓을 수도 있고 굴릴 수도 있어요.","answer":"X","reason_options":[{"t":"잘 쌓이지만 평평해서 굴러가지 않으니까","correct":true},{"t":"모서리로 세우면 굴러가니까","mis":"M1-1-u2-X08"}],"explanation":["상자 모양은 쌓을 수는 있지만 굴러가지 않아요.","평평한 부분이 바닥에 닿아요.","둘 다 할 수 있는 것은 기둥 모양이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#8','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C3',4,'mc','auto','주사위가 공 모양이라면 놀이할 때 어떤 일이 생길까요?',ARRAY['M1-1-u2-X08','M1-1-u2-X06']::text[],true,'{"seq":8,"concept":"M1-1-u2-C3","difficulty":4,"kind":"mc","stem":"주사위가 공 모양이라면 놀이할 때 어떤 일이 생길까요?","options":[{"t":"굴러가다 멈추지 않아 숫자를 읽기 어려워요","correct":true},{"t":"더 높이 쌓을 수 있어요","mis":"M1-1-u2-X08"},{"t":"모서리가 더 뾰족해져요","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 평평한 부분이 없어 잘 멈추지 않아요.","그래서 위쪽 숫자를 정하기 어려워요.","주사위가 상자 모양인 까닭을 생각해 보세요."],"variant_rule":{"alt":[{"stem":"자동차 바퀴가 상자 모양이라면 어떤 일이 생길까요?","options":[{"t":"굴러가지 않아 자동차가 잘 움직이지 못해요","correct":true},{"t":"여러 방향으로 더 잘 굴러가요","mis":"M1-1-u2-X08"},{"t":"바퀴가 공처럼 둥글어져요","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 평평해서 굴러가지 않아요.","그래서 바퀴로 쓰기 어려워요.","바퀴가 기둥 모양인 까닭을 생각해 보세요."],"asset":null},{"stem":"축구공이 상자 모양이라면 어떤 일이 생길까요?","options":[{"t":"차도 잘 굴러가지 않아 축구하기 어려워요","correct":true},{"t":"더 멀리 굴러가요","mis":"M1-1-u2-X08"},{"t":"둥근 부분이 더 많아져요","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 평평해서 굴러가지 않아요.","그래서 공놀이가 어려워요.","축구공이 공 모양인 까닭을 생각해 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#9','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C3',4,'essay','teacher','기둥 모양을 「쌓을 때」와 「굴릴 때」 각각 어떻게 놓아야 하는지 까닭과 함께 써 보세요.','{}'::text[],true,'{"seq":9,"concept":"M1-1-u2-C3","difficulty":4,"kind":"essay","stem":"기둥 모양을 「쌓을 때」와 「굴릴 때」 각각 어떻게 놓아야 하는지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 쌓을 때는 세워요 — 위와 아래가 평평해서 맞닿으니까. 굴릴 때는 눕혀요 — 둥근 옆이 바닥에 닿으니까.","scoring_points":["쌓을 때는 세운다고 했는가","굴릴 때는 눕힌다고 했는가","평평한 부분·둥근 부분으로 까닭을 댔는가"]},"explanation":["세우면 평평한 부분이 맞닿아요.","눕히면 둥근 옆이 바닥에 닿아요.","놓는 방향이 쓰임을 바꿔요."],"variant_rule":{"alt":[{"stem":"상자 모양과 공 모양 가운데 탑 쌓기 놀이에 알맞은 것과 굴리기 놀이에 알맞은 것을 고르고 까닭을 써 보세요.","answer_guide":{"answer":"예: 탑 쌓기에는 상자 모양 — 평평한 부분끼리 맞닿아 잘 쌓여요. 굴리기에는 공 모양 — 둥근 부분만 있어 여러 방향으로 잘 굴러가요.","scoring_points":["탑 쌓기에 상자 모양을 골랐는가","굴리기에 공 모양을 골랐는가","평평한·둥근 부분으로 까닭을 댔는가"]},"explanation":["쌓으려면 평평한 부분이 필요해요.","굴리려면 둥근 부분이 필요해요.","부분이 쓰임을 정해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L03_challenge#10','math',1,1,'u2','L03','g1_1_math_u2_L03_challenge','lesson_challenge','M1-1-u2-C2',4,'mc','auto','다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?',ARRAY['M1-1-u2-X04']::text[],true,'{"seq":10,"concept":"M1-1-u2-C2","difficulty":4,"kind":"mc","stem":"다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"여러 방향으로 잘 굴러가요","correct":true},{"t":"둥근 부분이 있어요","mis":"M1-1-u2-X04"},{"t":"뾰족한 부분이 없어요","mis":"M1-1-u2-X04"}],"explanation":["여러 방향으로 잘 굴러가는 것은 공 모양뿐이에요.","둥근 부분·뾰족한 곳 없음은 기둥 모양에도 맞아요.","「~에만」 맞는지 다른 두 모양에도 대 보세요."],"variant_rule":{"alt":[{"stem":"다음 가운데 상자 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"뾰족한 부분이 있어요","correct":true},{"t":"평평한 부분이 있어요","mis":"M1-1-u2-X05"},{"t":"쌓을 수 있어요","mis":"M1-1-u2-X07"}],"explanation":["뾰족한 부분은 상자 모양에만 있어요.","평평한 부분·쌓기는 기둥 모양에도 맞아요.","다른 두 모양에도 대 보세요."],"asset":null},{"stem":"다음 가운데 기둥 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"평평한 부분과 둥근 부분이 함께 있어요","correct":true},{"t":"둥근 부분이 있어요","mis":"M1-1-u2-X04"},{"t":"평평한 부분이 있어요","mis":"M1-1-u2-X05"}],"explanation":["평평한 부분과 둥근 부분이 함께 있는 것은 기둥뿐이에요.","둥근 부분은 공, 평평한 부분은 상자에도 있어요.","다른 두 모양에도 대 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#1','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',1,'mc','auto','의자에서 앉는 자리로 어울리는 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X07']::text[],true,'{"seq":1,"concept":"M1-1-u2-C4","difficulty":1,"kind":"mc","stem":"의자에서 앉는 자리로 어울리는 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["앉는 자리는 평평하고 굴러가지 않아야 해요.","그래서 상자 모양이 어울려요.","그 자리가 멈춰 있어야 하는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"장난감 자동차의 바퀴로 어울리는 모양은 무엇인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X10"},{"t":"공 모양","mis":"M1-1-u2-X09"}],"explanation":["바퀴는 앞으로 굴러가야 해요.","눕힌 기둥은 한 방향으로 굴러가요.","그 자리가 굴러가야 하는지 먼저 생각해요."],"asset":null},{"stem":"눈사람의 머리로 어울리는 모양은 무엇인가요?","options":[{"t":"공 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X10"},{"t":"기둥 모양","mis":"M1-1-u2-X10"}],"explanation":["눈사람 머리는 둥글둥글해요.","둥근 부분만 있는 공 모양이 어울려요.","나타내고 싶은 생김새를 먼저 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#2','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',1,'mc','auto','블록으로 탑을 높이 쌓으려고 해요. 가장 잘 쌓이는 모양은 무엇인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X07']::text[],true,'{"seq":2,"concept":"M1-1-u2-C4","difficulty":1,"kind":"mc","stem":"블록으로 탑을 높이 쌓으려고 해요. 가장 잘 쌓이는 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X08"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["상자 모양은 평평한 부분끼리 맞닿아요.","그래서 높이 쌓아도 잘 무너지지 않아요.","위에 올릴 자리가 평평한지 보세요."],"variant_rule":{"alt":[{"stem":"공을 굴려 넣는 놀이 길을 만들어요. 길 따라 굴러갈 것으로 알맞은 모양은 무엇인가요?","options":[{"t":"공 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X08"},{"t":"세운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["공 모양은 어느 쪽으로든 잘 굴러가요.","굴러갈 것은 둥근 부분이 있어야 해요.","그 자리가 굴러가야 하는지 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#3','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',1,'sa','auto','상자·기둥·공 모양으로 로봇을 만들었어요. 상자 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-1-u2-C4","difficulty":1,"kind":"sa","stem":"상자·기둥·공 모양으로 로봇을 만들었어요. 상자 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["상자 모양만 골라 세어요.","모두 4개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":4},{"solid":"cyl","n":2},{"solid":"ball","n":1}],"name":"로봇"},"variant_rule":{"solidart":{"ask":"box","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#4','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',1,'mc','auto','만드는 데 쓴 공 모양은 몇 개인가요?',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":4,"concept":"M1-1-u2-C4","difficulty":1,"kind":"mc","stem":"만드는 데 쓴 공 모양은 몇 개인가요?","options":[{"t":"3","correct":true},{"t":"2","mis":"M1-1-u2-X11"},{"t":"4","mis":"M1-1-u2-X11"}],"explanation":["공 모양만 골라 세어요.","모두 3개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":2},{"solid":"ball","n":3}],"name":"눈사람 가족"},"variant_rule":{"solidart":{"ask":"ball","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#5','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',2,'mc','auto','기차를 만들었어요. 누운 기둥도 잘 보고, 기둥 모양은 몇 개인지 고르세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":5,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"기차를 만들었어요. 누운 기둥도 잘 보고, 기둥 모양은 몇 개인지 고르세요.","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u2-X11"},{"t":"8","mis":"M1-1-u2-X11"}],"explanation":["서 있는 기둥과 누운 기둥을 모두 세어요 — 누운 기둥도 기둥 모양이에요.","모두 4개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":4},{"solid":"ball","n":1}],"name":"기차","lay":true},"variant_rule":{"solidart":{"ask":"cyl","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#6','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',2,'mc','auto','공이 굴러 내려가는 길을 만들어요. 공이 옆으로 떨어지지 않게 길 양옆에 놓을 것으로 알맞은 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X07']::text[],true,'{"seq":6,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"공이 굴러 내려가는 길을 만들어요. 공이 옆으로 떨어지지 않게 길 양옆에 놓을 것으로 알맞은 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["울타리는 굴러가지 않고 멈춰 있어야 해요.","상자 모양은 밀려도 굴러가지 않아요.","그 자리가 멈춰 있어야 하는지 먼저 생각해요."],"variant_rule":{"alt":[{"stem":"수레를 만들어요. 수레를 끌 때 굴러가야 하는 바퀴로 알맞은 모양은 무엇인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X10"},{"t":"공 모양","mis":"M1-1-u2-X09"}],"explanation":["바퀴는 한 방향으로 굴러가야 해요.","눕힌 기둥이 알맞아요.","공은 여러 방향으로 굴러 수레가 비틀거려요."],"asset":null},{"stem":"인형 집의 지붕 밑 기둥을 만들어요. 똑바로 세워 지붕을 받칠 것으로 알맞은 모양은 무엇인가요?","options":[{"t":"세운 기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["세운 기둥은 위가 평평해 지붕을 받칠 수 있어요.","공이나 누운 기둥은 위가 둥글어요.","위에 올릴 자리가 평평한지 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#7','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',2,'match','auto','만들 자리와 어울리는 모양을 줄로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u2-C4","difficulty":2,"kind":"match","stem":"만들 자리와 어울리는 모양을 줄로 이어 보세요.","pairs":[{"l":"굴러가는 바퀴","r":"기둥 모양"},{"l":"앉는 자리","r":"상자 모양"},{"l":"눈사람 머리","r":"공 모양"}],"mis":"M1-1-u2-X10","explanation":["바퀴는 굴러가야 하니 기둥, 앉는 자리는 평평해야 하니 상자예요.","눈사람 머리는 둥근 공 모양이에요.","그 자리에 필요한 특징을 먼저 떠올려요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 만들 자리와 어울리는 모양을 줄로 이어 보세요.","pairs":[{"l":"높이 쌓는 탑","r":"상자 모양"},{"l":"굴리는 볼링공","r":"공 모양"},{"l":"세워 두는 깃대","r":"기둥 모양"}],"explanation":["탑은 평평해야 하니 상자, 볼링공은 굴러야 하니 공이에요.","깃대는 세워 두는 기둥 모양이에요.","그 자리에 필요한 특징을 먼저 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#8','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',2,'sa','auto','만드는 데 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-1-u2-C4","difficulty":2,"kind":"sa","stem":"만드는 데 쓴 모양은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["모양을 종류별로 세어 모두 더해요.","상자 3개, 기둥 3개, 공 2개 — 모두 8개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":3},{"solid":"ball","n":2}],"name":"성"},"variant_rule":{"solidart":{"ask":"total","n":[1,4]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#9','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',2,'ox','auto','공 모양으로는 높은 탑을 쌓기 어려워요.',ARRAY['M1-1-u2-X10']::text[],true,'{"seq":9,"concept":"M1-1-u2-C4","difficulty":2,"kind":"ox","stem":"공 모양으로는 높은 탑을 쌓기 어려워요.","answer":"O","reason_options":[{"t":"평평한 부분이 없어 위에 올리면 굴러떨어지니까","correct":true},{"t":"공 모양은 너무 무거우니까","mis":"M1-1-u2-X10"}],"mis":"M1-1-u2-X10","explanation":["공 모양은 평평한 부분이 없어요.","그래서 쌓으면 굴러떨어져요.","탑에는 평평한 부분이 있는 모양을 써요."],"variant_rule":{"alt":[{"stem":"상자 모양은 자동차 바퀴로 쓰기 좋아요.","answer":"X","reason_options":[{"t":"평평해서 굴러가지 않으니까","correct":true},{"t":"상자 모양은 튼튼하니까","mis":"M1-1-u2-X10"}],"explanation":["바퀴는 굴러가야 해요.","상자 모양은 굴러가지 않아요.","바퀴에는 둥근 부분이 있는 모양을 써요."],"asset":null},{"stem":"세운 기둥 모양 위에 상자 모양을 올려 책상을 만들 수 있어요.","answer":"O","reason_options":[{"t":"세운 기둥은 위가 평평해 상자를 받칠 수 있으니까","correct":true},{"t":"기둥은 어떻게 놓아도 굴러가니까","mis":"M1-1-u2-X07"}],"explanation":["세운 기둥의 위는 평평해요.","그래서 상자를 올려 받칠 수 있어요.","기둥은 놓는 방향에 따라 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_basic#10','math',1,1,'u2','L04','g1_1_math_u2_L04_basic','lesson_basic','M1-1-u2-C4',3,'mc','auto','가장 많이 쓴 모양은 무엇인가요?',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":10,"concept":"M1-1-u2-C4","difficulty":3,"kind":"mc","stem":"가장 많이 쓴 모양은 무엇인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X11"},{"t":"공 모양","mis":"M1-1-u2-X11"}],"explanation":["상자 2개, 기둥 5개, 공 3개예요.","가장 많은 것은 기둥 모양이에요.","모양마다 따로 세어 수를 견주어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":5},{"solid":"ball","n":3}],"name":"놀이터","lay":true},"variant_rule":{"solidart":{"ask":"most","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#1','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',2,'mc','auto','만드는 데 쓴 상자 모양은 몇 개인가요?',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":1,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"만드는 데 쓴 상자 모양은 몇 개인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M1-1-u2-X11"},{"t":"6","mis":"M1-1-u2-X11"}],"explanation":["상자 모양만 골라 세어요.","모두 5개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":5},{"solid":"cyl","n":3},{"solid":"ball","n":2}],"name":"집","lay":true},"variant_rule":{"solidart":{"ask":"box","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#2','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',2,'mc','auto','기둥 모양을 탑의 기둥으로 쓰려고 해요. 어떻게 놓아야 하나요?',ARRAY['M1-1-u2-X07']::text[],true,'{"seq":2,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"기둥 모양을 탑의 기둥으로 쓰려고 해요. 어떻게 놓아야 하나요?","options":[{"t":"평평한 부분이 위아래로 가게 세워요","correct":true},{"t":"둥근 옆이 바닥에 닿게 눕혀요","mis":"M1-1-u2-X07"},{"t":"어떻게 놓아도 똑같아요","mis":"M1-1-u2-X07"}],"explanation":["세우면 위가 평평해 다른 모양을 올릴 수 있어요.","눕히면 둥근 옆 때문에 굴러가요.","같은 기둥도 놓는 방향에 따라 쓰임이 달라요."],"variant_rule":{"alt":[{"stem":"기둥 모양을 굴러가는 바퀴로 쓰려고 해요. 어떻게 놓아야 하나요?","options":[{"t":"둥근 옆이 바닥에 닿게 눕혀요","correct":true},{"t":"평평한 부분이 바닥에 닿게 세워요","mis":"M1-1-u2-X07"},{"t":"어떻게 놓아도 똑같아요","mis":"M1-1-u2-X07"}],"explanation":["눕히면 둥근 옆이 바닥에 닿아 굴러가요.","세우면 평평한 부분이 닿아 멈춰 있어요.","같은 기둥도 놓는 방향에 따라 쓰임이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#3','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',3,'error','auto','친구가 만든 성을 보고 한 말이에요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":3,"concept":"M1-1-u2-C4","difficulty":3,"kind":"error","stem":"친구가 만든 성을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「상자 모양을 2개 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「공 모양을 2개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「모두 7개를 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["상자 모양은 3개예요 — 하나를 빠뜨렸어요.","공 2개, 모두 7개는 맞아요.","모양마다 색을 정해 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":2},{"solid":"ball","n":2}],"name":"성"},"variant_rule":{"alt":[{"stem":"친구가 만든 기차를 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「기둥 모양을 2개 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「상자 모양을 3개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「공 모양을 1개 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["기둥 모양은 4개예요 — 누운 기둥을 빠뜨렸어요.","누운 기둥도 기둥 모양이에요.","모양마다 색을 정해 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":4},{"solid":"ball","n":1}],"name":"기차","lay":true}},{"stem":"친구가 만든 로봇을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「모두 9개를 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「상자 모양을 4개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「기둥 모양을 3개 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["4 + 3 + 1 = 8, 모두 8개예요.","공 1개를 두 번 센 셈이에요.","센 모양에 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":4},{"solid":"cyl","n":3},{"solid":"ball","n":1}],"name":"로봇"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#4','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',3,'mc','auto','눈사람을 만들 때 공 모양을 쓰는 까닭은 무엇인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X06']::text[],true,'{"seq":4,"concept":"M1-1-u2-C4","difficulty":3,"kind":"mc","stem":"눈사람을 만들 때 공 모양을 쓰는 까닭은 무엇인가요?","options":[{"t":"둥글둥글한 몸통과 머리를 나타내기 좋으니까","correct":true},{"t":"공 모양은 잘 쌓여서 무너지지 않으니까","mis":"M1-1-u2-X08"},{"t":"공 모양에는 뾰족한 부분이 있으니까","mis":"M1-1-u2-X06"}],"explanation":["눈사람은 둥근 생김새를 나타내야 해요.","공 모양은 쌓기 어렵고 뾰족한 곳도 없어요.","나타내고 싶은 생김새에 맞는 모양을 골라요."],"variant_rule":{"alt":[{"stem":"주사위 놀이 판의 말을 상자 모양으로 만드는 까닭은 무엇인가요?","options":[{"t":"평평해서 놓은 자리에 가만히 서 있으니까","correct":true},{"t":"여러 방향으로 잘 굴러가니까","mis":"M1-1-u2-X08"},{"t":"둥근 부분이 있으니까","mis":"M1-1-u2-X04"}],"explanation":["말은 판 위에 멈춰 있어야 해요.","상자 모양은 굴러가지 않아요.","그 자리에 필요한 특징을 먼저 떠올려요."],"asset":null},{"stem":"물레방아의 돌아가는 통을 기둥 모양으로 만드는 까닭은 무엇인가요?","options":[{"t":"눕히면 한 방향으로 돌아가니까","correct":true},{"t":"세우면 잘 쌓이니까","mis":"M1-1-u2-X07"},{"t":"뾰족한 부분이 있으니까","mis":"M1-1-u2-X06"}],"explanation":["물레방아 통은 한쪽으로 빙글빙글 돌아야 해요.","눕힌 기둥은 한 방향으로 굴러가듯 돌아요.","그 자리에 필요한 특징을 먼저 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#5','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',3,'sa','auto','만드는 데 쓴 모양은 모두 몇 개인가요? 누운 기둥도 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u2-C4","difficulty":3,"kind":"sa","stem":"만드는 데 쓴 모양은 모두 몇 개인가요? 누운 기둥도 세어 숫자로 쓰세요.","answer":["10"],"explanation":["모양을 종류별로 세어 모두 더해요 — 누운 기둥도 넣어요.","상자 3개, 기둥 4개, 공 3개 — 모두 10개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":4},{"solid":"ball","n":3}],"name":"놀이 기구","lay":true},"variant_rule":{"solidart":{"ask":"total","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#6','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',3,'mc','auto','바퀴를 공 모양으로 단 자동차와 기둥 모양으로 단 자동차가 있어요. 앞으로 곧게 가기 좋은 쪽과 그 까닭은 어느 것인가요?',ARRAY['M1-1-u2-X09','M1-1-u2-X04']::text[],true,'{"seq":6,"concept":"M1-1-u2-C4","difficulty":3,"kind":"mc","stem":"바퀴를 공 모양으로 단 자동차와 기둥 모양으로 단 자동차가 있어요. 앞으로 곧게 가기 좋은 쪽과 그 까닭은 어느 것인가요?","options":[{"t":"기둥 바퀴 — 한 방향으로 굴러가니까","correct":true},{"t":"공 바퀴 — 여러 방향으로 잘 굴러가니까","mis":"M1-1-u2-X09"},{"t":"둘 다 같아요 — 둘 다 둥근 부분이 있으니까","mis":"M1-1-u2-X04"}],"explanation":["눕힌 기둥 바퀴는 한 방향으로 굴러가요.","공 바퀴는 여러 방향으로 굴러 이리저리 흔들려요.","둥근 곳이 있다는 것만으로는 같지 않아요."],"variant_rule":{"alt":[{"stem":"물건을 쌓아 옮기는 수레의 바닥판을 만들어요. 알맞은 모양과 그 까닭은 어느 것인가요?","options":[{"t":"상자 모양 — 평평해서 물건을 올려도 굴러떨어지지 않으니까","correct":true},{"t":"공 모양 — 둥글어서 물건이 잘 미끄러지니까","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양 — 한 방향으로 굴러가니까","mis":"M1-1-u2-X07"}],"explanation":["바닥판은 평평하고 멈춰 있어야 해요.","공·누운 기둥은 위가 둥글어 물건이 굴러떨어져요.","그 자리에 필요한 특징을 먼저 떠올려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#7','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',3,'ox','auto','만든 것에서 누워 있는 기둥은 기둥 모양으로 세지 않아요.',ARRAY['M1-1-u2-X03']::text[],true,'{"seq":7,"concept":"M1-1-u2-C4","difficulty":3,"kind":"ox","stem":"만든 것에서 누워 있는 기둥은 기둥 모양으로 세지 않아요.","answer":"X","reason_options":[{"t":"누워 있어도 평평한 위·아래와 둥근 옆이 있는 기둥 모양이니까","correct":true},{"t":"서 있어야 기둥 모양이니까","mis":"M1-1-u2-X03"}],"mis":"M1-1-u2-X11","explanation":["누운 기둥도 기둥 모양이에요.","놓인 방향은 모양을 바꾸지 않아요.","셀 때 누운 것을 빠뜨리지 않게 점을 찍어요."],"variant_rule":{"alt":[{"stem":"만든 것에서 작은 공 모양도 공 모양으로 세어야 해요.","answer":"O","reason_options":[{"t":"크기가 작아도 둥근 부분만 있는 공 모양이니까","correct":true},{"t":"작은 것은 장식이라 세지 않으니까","mis":"M1-1-u2-X11"}],"explanation":["작아도 공 모양이에요.","크기는 모양을 가르는 기준이 아니에요.","작은 모양도 빠뜨리지 않고 세어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#8','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',4,'essay','teacher','상자·기둥·공 모양을 하나 이상씩 써서 놀이터 기구를 하나 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M1-1-u2-C4","difficulty":4,"kind":"essay","stem":"상자·기둥·공 모양을 하나 이상씩 써서 놀이터 기구를 하나 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 미끄럼틀을 만들어요. 계단은 상자 모양 — 평평해서 밟기 좋아요. 기둥은 세운 기둥 모양 — 위가 평평해 판을 받쳐요. 꼭대기 장식은 공 모양 — 둥글어서 예뻐요.","scoring_points":["세 모양을 모두 썼는가","모양마다 쓸 자리를 말했는가","평평하다·굴러간다·둥글다 같은 특징으로 까닭을 댔는가"]},"explanation":["만들 것을 먼저 정해요.","자리마다 필요한 특징을 떠올려요.","그 특징이 있는 모양을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#9','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',4,'mc','auto','가장 많이 쓴 모양은 무엇인가요? 누운 기둥도 세어 보세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":9,"concept":"M1-1-u2-C4","difficulty":4,"kind":"mc","stem":"가장 많이 쓴 모양은 무엇인가요? 누운 기둥도 세어 보세요.","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X11"},{"t":"공 모양","mis":"M1-1-u2-X11"}],"explanation":["상자 3개, 기둥 5개, 공 2개예요.","가장 많은 것은 기둥 모양이에요 — 누운 것을 빼면 틀려요.","모양마다 따로 세어 수를 견주어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":5},{"solid":"ball","n":2}],"name":"자동차 공장","lay":true},"variant_rule":{"solidart":{"ask":"most","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L04_challenge#10','math',1,1,'u2','L04','g1_1_math_u2_L04_challenge','lesson_challenge','M1-1-u2-C4',4,'mc','auto','상자 모양 4개만 가지고 만들 수 없는 것은 어느 것인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X10']::text[],true,'{"seq":10,"concept":"M1-1-u2-C4","difficulty":4,"kind":"mc","stem":"상자 모양 4개만 가지고 만들 수 없는 것은 어느 것인가요?","options":[{"t":"앞으로 굴러가는 수레","correct":true},{"t":"높은 탑","mis":"M1-1-u2-X08"},{"t":"계단","mis":"M1-1-u2-X10"}],"explanation":["상자 모양만으로는 굴러가는 부분을 만들 수 없어요.","탑과 계단은 상자를 쌓아 만들 수 있어요.","굴러가려면 둥근 부분이 있는 모양이 필요해요."],"variant_rule":{"alt":[{"stem":"공 모양 4개만 가지고 만들 수 없는 것은 어느 것인가요?","options":[{"t":"높이 쌓은 탑","correct":true},{"t":"눈사람","mis":"M1-1-u2-X10"},{"t":"굴러가는 볼링 놀이","mis":"M1-1-u2-X08"}],"explanation":["공 모양은 평평한 부분이 없어 쌓을 수 없어요.","눈사람·볼링 놀이는 공 모양으로 할 수 있어요.","쌓으려면 평평한 부분이 있는 모양이 필요해요."],"asset":null},{"stem":"기둥 모양 4개만 가지고 만들 수 없는 것은 어느 것인가요?","options":[{"t":"어느 쪽으로든 굴러가는 공 놀이","correct":true},{"t":"쌓은 탑","mis":"M1-1-u2-X07"},{"t":"한 방향으로 굴러가는 바퀴","mis":"M1-1-u2-X07"}],"explanation":["기둥은 한 방향으로만 굴러가요.","세워 쌓기와 눕혀 굴리기는 기둥으로 할 수 있어요.","여러 방향으로 굴러가는 것은 공 모양뿐이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#1','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',1,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X02']::text[],true,'{"seq":1,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"농구공","correct":true},{"t":"선물 상자","mis":"M1-1-u2-X01"},{"t":"얼음","mis":"M1-1-u2-X02"}],"explanation":["선물 상자·얼음·도시락은 상자 모양이에요.","농구공만 공 모양이에요.","크기나 쓰임이 아니라 생김새를 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🎁","name":"선물 상자"},{"icon":"🧊","name":"얼음"},{"icon":"🏀","name":"농구공"},{"icon":"🍱","name":"도시락"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#2','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',1,'mc','auto','딱풀과 통조림의 같은 점은 무엇인가요?',ARRAY['M1-1-u2-X12','M1-1-u2-X01']::text[],true,'{"seq":2,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"딱풀과 통조림의 같은 점은 무엇인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"둘 다 먹을 수 있어요","mis":"M1-1-u2-X12"},{"t":"둘 다 크기가 같아요","mis":"M1-1-u2-X01"}],"explanation":["딱풀도 통조림도 위·아래가 평평하고 옆이 둥글어요.","쓰임·크기는 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."],"variant_rule":{"alt":[{"stem":"주사위와 택배 상자의 같은 점은 무엇인가요?","options":[{"t":"둘 다 상자 모양이에요","correct":true},{"t":"둘 다 놀잇감이에요","mis":"M1-1-u2-X12"},{"t":"둘 다 크기가 같아요","mis":"M1-1-u2-X01"}],"explanation":["둘 다 평평한 부분과 뾰족한 부분이 있어요.","쓰임·크기는 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."],"asset":null},{"stem":"구슬과 축구공의 같은 점은 무엇인가요?","options":[{"t":"둘 다 공 모양이에요","correct":true},{"t":"둘 다 발로 차요","mis":"M1-1-u2-X12"},{"t":"둘 다 색깔이 같아요","mis":"M1-1-u2-X12"}],"explanation":["둘 다 둥근 부분만 있어요.","쓰임·색깔은 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#3','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',1,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#4','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',1,'sa','auto','기둥 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M1-1-u2-C5","difficulty":1,"kind":"sa","stem":"기둥 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["기둥 모양은 북·건전지예요.","모두 2개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🥁","name":"북"},{"icon":"🎲","name":"주사위"},{"icon":"🎾","name":"테니스공"},{"icon":"🔋","name":"건전지"},{"icon":"🧱","name":"벽돌"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#5','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X13']::text[],true,'{"seq":5,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"공 모양","mis":"M1-1-u2-X13"}],"explanation":["보이는 곳에 뾰족한 모서리 끝이 있어요.","뾰족한 부분은 상자 모양에만 있어요.","보이는 부분에서 확실한 단서를 찾아요."],"asset":{"type":"solid_row","items":[{"solid":"box","peek":true}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X13"}],"explanation":["위는 평평한 동그라미, 옆은 둥글어요.","평평한 곳과 둥근 곳이 함께 있으면 기둥 모양이에요.","보이는 부분에서 확실한 단서를 찾아요."],"asset":{"type":"solid_row","items":[{"solid":"cyl","peek":true}]}},{"stem":"이번에는 다른 보기예요. 주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X13"}],"explanation":["보이는 곳이 모두 둥글고 평평한 곳이 없어요.","동그란 지붕처럼 둥근 것은 공 모양이에요.","보이는 부분에서 확실한 단서를 찾아요."],"asset":{"type":"solid_row","items":[{"solid":"ball","peek":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#6','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',2,'mc','auto','주사위와 구슬의 다른 점은 무엇인가요?',ARRAY['M1-1-u2-X12']::text[],true,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주사위와 구슬의 다른 점은 무엇인가요?","options":[{"t":"주사위는 뾰족한 부분이 있고 구슬은 없어요","correct":true},{"t":"주사위는 크고 구슬은 작아요","mis":"M1-1-u2-X12"},{"t":"구슬만 장난감이에요","mis":"M1-1-u2-X12"}],"explanation":["주사위는 상자 모양, 구슬은 공 모양이에요.","크기·쓰임은 모양의 다른 점이 아니에요.","생김새로만 말해 보세요."],"variant_rule":{"alt":[{"stem":"통조림과 테니스공의 다른 점은 무엇인가요?","options":[{"t":"통조림은 평평한 부분이 있고 테니스공은 없어요","correct":true},{"t":"통조림은 먹는 것이에요","mis":"M1-1-u2-X12"},{"t":"둘 다 둥글어서 다른 점이 없어요","mis":"M1-1-u2-X04"}],"explanation":["통조림은 기둥 모양, 테니스공은 공 모양이에요.","둥근 곳이 있다고 같은 모양은 아니에요.","평평한 곳이 있는지 견주어요."],"asset":null},{"stem":"벽돌과 북의 다른 점은 무엇인가요?","options":[{"t":"북은 옆이 둥글고 벽돌은 둥근 부분이 없어요","correct":true},{"t":"벽돌이 더 무거워요","mis":"M1-1-u2-X12"},{"t":"둘 다 평평해서 다른 점이 없어요","mis":"M1-1-u2-X05"}],"explanation":["벽돌은 상자 모양, 북은 기둥 모양이에요.","평평한 곳이 있다고 같은 모양은 아니에요.","둥근 곳이 있는지 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#7','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',2,'match','auto','눈을 감고 만진 느낌과 알맞은 모양을 줄로 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M1-1-u2-C5","difficulty":2,"kind":"match","stem":"눈을 감고 만진 느낌과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"뾰족한 곳이 만져져요","r":"상자 모양"},{"l":"평평한 곳과 둥근 곳이 다 만져져요","r":"기둥 모양"},{"l":"어디를 만져도 둥글기만 해요","r":"공 모양"}],"mis":"M1-1-u2-X13","explanation":["뾰족한 곳은 상자, 평평·둥근 곳이 다 있으면 기둥이에요.","둥근 곳만 있으면 공이에요.","만져지는 단서를 모두 써서 정해요."],"variant_rule":{"alt":[{"stem":"굴려 본 모습과 알맞은 모양을 줄로 이어 보세요.","pairs":[{"l":"어느 쪽으로든 굴러가요","r":"공 모양"},{"l":"눕히면 한 방향으로 굴러가요","r":"기둥 모양"},{"l":"밀어도 굴러가지 않아요","r":"상자 모양"}],"explanation":["여러 방향은 공, 한 방향은 눕힌 기둥이에요.","굴러가지 않으면 상자예요.","굴러간 모습을 떠올려 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#8','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',2,'ox','auto','공 모양은 쌓을 수 있어요.',ARRAY['M1-1-u2-X08']::text[],true,'{"seq":8,"concept":"M1-1-u2-C5","difficulty":2,"kind":"ox","stem":"공 모양은 쌓을 수 있어요.","answer":"X","reason_options":[{"t":"평평한 부분이 없어 굴러떨어지니까","correct":true},{"t":"평평한 부분끼리 맞닿으니까","mis":"M1-1-u2-X08"}],"mis":"M1-1-u2-X13","explanation":["공 모양은 쌓을 수 없어요.","「쌓을 수 있어요」는 상자 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#9','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',2,'mc','auto','카드 두 장을 뒤집었더니 북과 건전지가 나왔어요. 같은 모양 짝인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X12']::text[],true,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"카드 두 장을 뒤집었더니 북과 건전지가 나왔어요. 같은 모양 짝인가요?","options":[{"t":"네, 둘 다 기둥 모양이에요","correct":true},{"t":"아니요, 크기가 달라요","mis":"M1-1-u2-X01"},{"t":"아니요, 쓰임이 달라요","mis":"M1-1-u2-X12"}],"explanation":["북도 건전지도 위·아래가 평평하고 옆이 둥글어요.","크기·쓰임이 달라도 같은 모양 짝이에요.","생김새로만 견주어요."],"variant_rule":{"alt":[{"stem":"카드 두 장을 뒤집었더니 구슬과 통조림이 나왔어요. 같은 모양 짝인가요?","options":[{"t":"아니요, 구슬은 공 모양, 통조림은 기둥 모양이에요","correct":true},{"t":"네, 둘 다 둥근 부분이 있어요","mis":"M1-1-u2-X04"},{"t":"네, 둘 다 작아요","mis":"M1-1-u2-X01"}],"explanation":["구슬은 둥근 부분만, 통조림은 평평한 곳도 있어요.","둥근 곳이 있다는 것만으로는 같은 모양이 아니에요.","평평한 곳이 있는지도 견주어요."],"asset":null},{"stem":"카드 두 장을 뒤집었더니 얼음과 주사위가 나왔어요. 같은 모양 짝인가요?","options":[{"t":"네, 둘 다 상자 모양이에요","correct":true},{"t":"아니요, 얼음은 차가워요","mis":"M1-1-u2-X12"},{"t":"아니요, 주사위에는 점이 있어요","mis":"M1-1-u2-X12"}],"explanation":["얼음도 주사위도 평평한 부분과 뾰족한 부분이 있어요.","차갑다·점이 있다는 생김새가 아니에요.","생김새로만 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_basic#10','math',1,1,'u2','L05','g1_1_math_u2_L05_basic','lesson_basic','M1-1-u2-C5',3,'error','auto','수아가 생각한 모양을 맞히는 놀이예요. 수아: 「평평한 부분이 있어요. 뾰족한 부분은 없어요.」 친구들의 대답 가운데 틀린 것은 어느 것인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X13','M1-1-u2-X06']::text[],true,'{"seq":10,"concept":"M1-1-u2-C5","difficulty":3,"kind":"error","stem":"수아가 생각한 모양을 맞히는 놀이예요. 수아: 「평평한 부분이 있어요. 뾰족한 부분은 없어요.」 친구들의 대답 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「상자 모양이야!」","correct":true,"mis_target":"M1-1-u2-X05"},{"t":"「기둥 모양이야!」","mis":"M1-1-u2-X13"},{"t":"「공 모양은 아니야.」","mis":"M1-1-u2-X06"}],"explanation":["뾰족한 부분이 없으니 상자 모양이 아니에요.","평평한 부분이 있으니 공도 아니에요 — 기둥 모양이에요.","단서를 하나씩 세 모양에 대 보세요."],"variant_rule":{"alt":[{"stem":"수아가 생각한 모양을 맞히는 놀이예요. 수아: 「둥근 부분이 있어요. 쌓을 수도 있어요.」 친구들의 대답 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「공 모양이야!」","correct":true,"mis_target":"M1-1-u2-X13"},{"t":"「기둥 모양이야!」","mis":"M1-1-u2-X13"},{"t":"「상자 모양은 아니야.」","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 쌓을 수 없어요.","둥근 부분이 있고 쌓을 수 있는 것은 기둥 모양이에요.","단서를 하나씩 세 모양에 대 보세요."],"asset":null},{"stem":"수아가 생각한 모양을 맞히는 놀이예요. 수아: 「평평한 부분이 없어요.」 친구들의 대답 가운데 틀린 것은 어느 것인가요?","options":[{"t":"「기둥 모양이야!」","correct":true,"mis_target":"M1-1-u2-X05"},{"t":"「공 모양이야!」","mis":"M1-1-u2-X13"},{"t":"「상자 모양은 아니야.」","mis":"M1-1-u2-X06"}],"explanation":["기둥 모양은 위·아래가 평평해요.","평평한 부분이 없는 것은 공 모양뿐이에요.","단서를 하나씩 세 모양에 대 보세요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#1','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X13','M1-1-u2-X05']::text[],true,'{"seq":1,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X05"}],"explanation":["위는 평평한 동그라미, 옆은 둥글어요.","평평한 곳과 둥근 곳이 함께 있으면 기둥 모양이에요.","보이는 부분의 단서를 모두 써요."],"asset":{"type":"solid_row","items":[{"solid":"cyl","peek":true}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X05"},{"t":"공 모양","mis":"M1-1-u2-X13"}],"explanation":["뾰족한 모서리 끝이 보여요.","뾰족한 부분은 상자 모양에만 있어요.","보이는 부분의 단서를 모두 써요."],"asset":{"type":"solid_row","items":[{"solid":"box","peek":true}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#2','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',2,'sa','auto','공 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M1-1-u2-C5","difficulty":2,"kind":"sa","stem":"공 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["공 모양은 구슬·당구공·배구공이에요.","모두 3개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🔮","name":"구슬"},{"icon":"🥫","name":"통조림"},{"icon":"🎱","name":"당구공"},{"icon":"📦","name":"택배 상자"},{"icon":"🏐","name":"배구공"},{"icon":"🪵","name":"통나무"},{"icon":"🧊","name":"얼음"}]},"variant_rule":{"solids":{"ask":"count","len":[6,7]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#3','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',3,'mc','auto','주머니 속 물건을 만졌더니 둥근 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?',ARRAY['M1-1-u2-X13']::text[],true,'{"seq":3,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"주머니 속 물건을 만졌더니 둥근 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"상자 모양은 아니에요","correct":true},{"t":"공 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["둥근 부분은 기둥에도 공에도 있어요.","그래서 둘 가운데 무엇인지는 아직 몰라요 — 상자가 아닌 것만 알아요.","단서가 모자라면 알 수 있는 것까지만 말해요."],"variant_rule":{"alt":[{"stem":"주머니 속 물건을 만졌더니 평평한 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"공 모양은 아니에요","correct":true},{"t":"상자 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["평평한 부분은 상자에도 기둥에도 있어요.","그래서 둘 가운데 무엇인지는 아직 몰라요 — 공이 아닌 것만 알아요.","단서가 모자라면 알 수 있는 것까지만 말해요."],"asset":null},{"stem":"주머니 속 물건을 만졌더니 뾰족한 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"상자 모양이에요","correct":true},{"t":"기둥 모양일 수도 있어요","mis":"M1-1-u2-X06"},{"t":"아직 알 수 없어요","mis":"M1-1-u2-X06"}],"explanation":["뾰족한 부분은 상자 모양에만 있어요.","그래서 이 단서 하나로 상자 모양이라고 알 수 있어요.","단서가 한 모양에만 있으면 바로 정할 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#4','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',3,'error','auto','준서가 축구공과 두루마리 휴지를 견주어 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X12']::text[],true,'{"seq":4,"concept":"M1-1-u2-C5","difficulty":3,"kind":"error","stem":"준서가 축구공과 두루마리 휴지를 견주어 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「둘 다 둥그니까 같은 공 모양이야.」","correct":true,"mis_target":"M1-1-u2-X04"},{"t":"「휴지는 평평한 부분이 있지만 축구공은 없어.」","mis":"M1-1-u2-X12"},{"t":"「둘 다 굴러갈 수 있어.」","mis":"M1-1-u2-X12"}],"explanation":["두루마리 휴지는 위·아래가 평평한 기둥 모양이에요.","둥근 곳이 있다는 것만으로 같은 모양이 아니에요.","평평한 곳이 있는지도 견주어요."],"variant_rule":{"alt":[{"stem":"준서가 주사위와 통조림을 견주어 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「둘 다 평평하니까 같은 상자 모양이야.」","correct":true,"mis_target":"M1-1-u2-X05"},{"t":"「통조림은 옆이 둥글지만 주사위는 아니야.」","mis":"M1-1-u2-X12"},{"t":"「둘 다 쌓을 수 있어.」","mis":"M1-1-u2-X12"}],"explanation":["통조림은 옆이 둥근 기둥 모양이에요.","평평한 곳이 있다는 것만으로 같은 모양이 아니에요.","둥근 곳이 있는지도 견주어요."],"asset":null},{"stem":"준서가 구슬과 배구공을 견주어 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「크기가 다르니까 다른 모양이야.」","correct":true,"mis_target":"M1-1-u2-X01"},{"t":"「둘 다 둥근 부분만 있어.」","mis":"M1-1-u2-X12"},{"t":"「둘 다 여러 방향으로 굴러가.」","mis":"M1-1-u2-X12"}],"explanation":["구슬도 배구공도 공 모양이에요.","크기는 모양을 가르는 기준이 아니에요.","생김새로만 견주어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#5','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',3,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#6','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',3,'mc','auto','모양 맞히기 놀이에서 두 단서를 들었어요. 「쌓을 수 있어요.」 「굴러갈 수도 있어요.」 어떤 모양인가요?',ARRAY['M1-1-u2-X08']::text[],true,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「쌓을 수 있어요.」 「굴러갈 수도 있어요.」 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X08"},{"t":"공 모양","mis":"M1-1-u2-X08"}],"explanation":["쌓을 수 있는 것은 상자와 기둥이에요.","그 가운데 굴러갈 수도 있는 것은 기둥이에요.","단서를 하나씩 더하며 후보를 줄여요."],"variant_rule":{"alt":[{"stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「뾰족한 부분이 없어요.」 「쌓을 수 없어요.」 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X06"}],"explanation":["뾰족한 부분이 없는 것은 기둥과 공이에요.","그 가운데 쌓을 수 없는 것은 공이에요.","단서를 하나씩 더하며 후보를 줄여요."],"asset":null},{"stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「평평한 부분이 있어요.」 「굴러가지 않아요.」 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X07"},{"t":"공 모양","mis":"M1-1-u2-X06"}],"explanation":["평평한 부분이 있는 것은 상자와 기둥이에요.","그 가운데 어떻게 놓아도 굴러가지 않는 것은 상자예요.","단서를 하나씩 더하며 후보를 줄여요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#7','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',3,'ox','auto','상자 모양은 둥근 부분이 있어요.',ARRAY['M1-1-u2-X04']::text[],true,'{"seq":7,"concept":"M1-1-u2-C5","difficulty":3,"kind":"ox","stem":"상자 모양은 둥근 부분이 있어요.","answer":"X","reason_options":[{"t":"평평한 부분과 뾰족한 부분만 있으니까","correct":true},{"t":"옆이 둥그니까","mis":"M1-1-u2-X04"}],"mis":"M1-1-u2-X13","explanation":["상자 모양은 둥근 부분이 없어요.","「둥근 부분이 있어요」는 기둥 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#8','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',4,'mc','auto','세 모양을 「상자, 기둥 / 공」 두 무리로 나누었어요. 무엇을 보고 나누었을까요?',ARRAY['M1-1-u2-X04','M1-1-u2-X12']::text[],true,'{"seq":8,"concept":"M1-1-u2-C5","difficulty":4,"kind":"mc","stem":"세 모양을 「상자, 기둥 / 공」 두 무리로 나누었어요. 무엇을 보고 나누었을까요?","options":[{"t":"평평한 부분이 있는가","correct":true},{"t":"둥근 부분이 있는가","mis":"M1-1-u2-X04"},{"t":"크기가 큰가","mis":"M1-1-u2-X12"}],"explanation":["상자와 기둥은 평평한 부분이 있고, 공은 없어요.","둥근 부분으로 나누면 「상자 / 기둥, 공」이 돼요.","나눈 무리마다 같은 점을 찾아요."],"variant_rule":{"alt":[{"stem":"세 모양을 「상자 / 기둥, 공」 두 무리로 나누었어요. 무엇을 보고 나누었을까요?","options":[{"t":"둥근 부분이 있는가","correct":true},{"t":"평평한 부분이 있는가","mis":"M1-1-u2-X05"},{"t":"색깔이 같은가","mis":"M1-1-u2-X12"}],"explanation":["기둥과 공은 둥근 부분이 있고, 상자는 없어요.","평평한 부분으로 나누면 「상자, 기둥 / 공」이 돼요.","나눈 무리마다 같은 점을 찾아요."],"asset":null},{"stem":"세 모양을 「상자 / 기둥, 공」 두 무리로 나누었어요. 다르게 말하면 무엇을 보고 나누었을까요?","options":[{"t":"굴러갈 수 있는가","correct":true},{"t":"쌓을 수 있는가","mis":"M1-1-u2-X08"},{"t":"크기가 큰가","mis":"M1-1-u2-X12"}],"explanation":["기둥과 공은 굴러갈 수 있고, 상자는 굴러가지 않아요.","쌓기로 나누면 「상자, 기둥 / 공」이 돼요.","나눈 무리마다 같은 점을 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#9','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',4,'essay','teacher','주머니 속 물건을 보지 않고 손으로만 만져서 어떤 모양인지 알아내려고 해요. 무엇을 만져 보고 어떻게 알아낼지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":4,"kind":"essay","stem":"주머니 속 물건을 보지 않고 손으로만 만져서 어떤 모양인지 알아내려고 해요. 무엇을 만져 보고 어떻게 알아낼지 써 보세요.","answer_guide":{"answer":"예: 먼저 뾰족한 곳이 있는지 만져요. 있으면 상자 모양이에요. 없으면 평평한 곳이 있는지 만져요. 있으면 기둥, 없으면 공 모양이에요.","scoring_points":["뾰족한·평평한·둥근 부분 가운데 둘 이상을 만져 본다고 했는가","만진 결과로 모양을 가르는 차례를 말했는가","한 단서만으로 서둘러 정하지 않았는가"]},"explanation":["부분 하나씩 만져 봐요.","뾰족하면 상자, 아니면 평평한 곳을 봐요.","단서를 차례로 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_L05_challenge#10','math',1,1,'u2','L05','g1_1_math_u2_L05_challenge','lesson_challenge','M1-1-u2-C5',4,'mc','auto','가은이가 생각한 물건이에요. 「굴릴 수 있지만, 세워 두면 쌓을 수도 있어요.」 알맞은 물건은 어느 것인가요?',ARRAY['M1-1-u2-X09','M1-1-u2-X08']::text[],true,'{"seq":10,"concept":"M1-1-u2-C5","difficulty":4,"kind":"mc","stem":"가은이가 생각한 물건이에요. 「굴릴 수 있지만, 세워 두면 쌓을 수도 있어요.」 알맞은 물건은 어느 것인가요?","options":[{"t":"통조림","correct":true},{"t":"구슬","mis":"M1-1-u2-X09"},{"t":"선물 상자","mis":"M1-1-u2-X08"}],"explanation":["굴릴 수도, 세워 쌓을 수도 있는 것은 기둥 모양이에요.","통조림이 기둥 모양이에요 — 구슬은 쌓을 수 없고 선물 상자는 굴러가지 않아요.","단서 두 개를 모두 만족하는지 확인해요."],"variant_rule":{"alt":[{"stem":"가은이가 생각한 물건이에요. 「쌓을 수 없고 어느 쪽으로든 굴러가요.」 알맞은 물건은 어느 것인가요?","options":[{"t":"테니스공","correct":true},{"t":"건전지","mis":"M1-1-u2-X09"},{"t":"도시락","mis":"M1-1-u2-X08"}],"explanation":["쌓을 수 없고 여러 방향으로 굴러가는 것은 공 모양이에요.","건전지는 한 방향으로만, 도시락은 굴러가지 않아요.","단서 두 개를 모두 만족하는지 확인해요."],"asset":null},{"stem":"가은이가 생각한 물건이에요. 「밀어도 굴러가지 않고 뾰족한 부분이 있어요.」 알맞은 물건은 어느 것인가요?","options":[{"t":"벽돌","correct":true},{"t":"북","mis":"M1-1-u2-X07"},{"t":"배구공","mis":"M1-1-u2-X08"}],"explanation":["굴러가지 않고 뾰족한 부분이 있는 것은 상자 모양이에요.","벽돌이 상자 모양이에요.","단서 두 개를 모두 만족하는지 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#1','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C1',1,'mc','auto','주사위는 어떤 모양인가요?',ARRAY['M1-1-u2-X02']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"주사위는 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X02"},{"t":"공 모양","mis":"M1-1-u2-X02"}],"explanation":["평평한 부분과 뾰족한 부분이 있어요.","그래서 상자 모양이에요.","이름이 아니라 생김새를 보고 나눠요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#2','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C1',1,'match','auto','물건과 같은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":1,"kind":"match","stem":"물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"선물 상자","r":"상자 모양"},{"l":"북","r":"기둥 모양"},{"l":"구슬","r":"공 모양"}],"mis":"M1-1-u2-X02","explanation":["선물 상자는 상자, 북은 기둥, 구슬은 공 모양이에요.","구슬은 이름에 「공」이 없어도 공 모양이에요.","생김새로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
