INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#4','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C3',1,'mc','auto','밀어도 굴러가지 않는 모양은 무엇인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X07']::text[],false,'{"seq":4,"concept":"M1-1-u2-C3","difficulty":1,"kind":"mc","stem":"밀어도 굴러가지 않는 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X08"},{"t":"기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["상자 모양은 평평한 부분이 바닥에 닿아요.","그래서 굴러가지 않아요.","기둥은 눕히면 굴러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#5','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C4',1,'sa','auto','만드는 데 쓴 상자 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u2-C4","difficulty":1,"kind":"sa","stem":"만드는 데 쓴 상자 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["상자 모양만 골라 세어요.","모두 3개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":2},{"solid":"ball","n":2}],"name":"탑"},"variant_rule":{"solidart":{"ask":"box","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#6','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C5',1,'mc','auto','북과 건전지의 같은 점은 무엇인가요?',ARRAY['M1-1-u2-X12','M1-1-u2-X01']::text[],false,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"북과 건전지의 같은 점은 무엇인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"둘 다 소리가 나요","mis":"M1-1-u2-X12"},{"t":"둘 다 크기가 같아요","mis":"M1-1-u2-X01"}],"explanation":["둘 다 위·아래가 평평하고 옆이 둥글어요.","쓰임·크기는 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#7','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C1',1,'blank','auto','주사위, 도시락, 얼음은 모두 (        ) 모양이에요.',ARRAY['M1-1-u2-X05','M1-1-u2-X02']::text[],false,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":1,"kind":"blank","stem":"주사위, 도시락, 얼음은 모두 (        ) 모양이에요.","options":[{"t":"상자","correct":true},{"t":"기둥","mis":"M1-1-u2-X05"},{"t":"공","mis":"M1-1-u2-X02"}],"explanation":["셋 다 평평한 부분과 뾰족한 부분이 있어요.","모두 상자 모양이에요.","크기가 달라도 같은 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#8','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C2',1,'ox','auto','공 모양은 뾰족한 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":8,"concept":"M1-1-u2-C2","difficulty":1,"kind":"ox","stem":"공 모양은 뾰족한 부분이 있어요.","answer":"X","reason_options":[{"t":"어디를 만져도 둥글기만 하니까","correct":true},{"t":"모서리 끝이 뾰족하니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["공 모양은 뾰족한 부분이 없어요.","「뾰족한 부분이 있어요」는 상자 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["flat","corner","round"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#9','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C5',2,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X12']::text[],true,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"통조림","correct":true},{"t":"구슬","mis":"M1-1-u2-X01"},{"t":"축구공","mis":"M1-1-u2-X12"}],"explanation":["구슬·축구공·당구공은 공 모양이에요.","통조림만 기둥 모양이에요.","평평한 곳이 있는지 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🔮","name":"구슬"},{"icon":"⚽","name":"축구공"},{"icon":"🥫","name":"통조림"},{"icon":"🎱","name":"당구공"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#10','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C2',2,'mc','auto','그림의 모양에서 평평한 부분은 어디인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X06']::text[],false,'{"seq":10,"concept":"M1-1-u2-C2","difficulty":2,"kind":"mc","stem":"그림의 모양에서 평평한 부분은 어디인가요?","options":[{"t":"위와 아래","correct":true},{"t":"둥근 옆","mis":"M1-1-u2-X05"},{"t":"평평한 부분이 없어요","mis":"M1-1-u2-X06"}],"explanation":["기둥 모양은 위와 아래가 평평해요.","옆은 둥근 부분이에요.","손바닥을 대면 판판한 곳이 평평한 부분이에요."],"asset":{"type":"solid_row","items":["cyl"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#11','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C3',2,'mc','auto','두 기둥을 밀었어요. 굴러가는 것은 어느 것인가요?',ARRAY['M1-1-u2-X07']::text[],false,'{"seq":11,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"두 기둥을 밀었어요. 굴러가는 것은 어느 것인가요?","options":[{"t":"② 누운 기둥","correct":true},{"t":"① 선 기둥","mis":"M1-1-u2-X07"},{"t":"둘 다 잘 굴러가요","mis":"M1-1-u2-X07"}],"explanation":["누운 기둥은 둥근 옆이 바닥에 닿아 굴러가요.","선 기둥은 평평한 아래가 닿아 굴러가지 않아요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#12','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C4',2,'mc','auto','장난감 자동차의 바퀴로 어울리는 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X09']::text[],false,'{"seq":12,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"장난감 자동차의 바퀴로 어울리는 모양은 무엇인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X10"},{"t":"공 모양","mis":"M1-1-u2-X09"}],"explanation":["바퀴는 앞으로 굴러가야 해요.","눕힌 기둥은 한 방향으로 굴러가요.","그 자리가 굴러가야 하는지 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#13','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":13,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"공 모양","mis":"M1-1-u2-X13"}],"explanation":["뾰족한 모서리 끝이 보여요.","뾰족한 부분은 상자 모양에만 있어요.","보이는 부분에서 확실한 단서를 찾아요."],"asset":{"type":"solid_row","items":[{"solid":"box","peek":true}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#14','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C1',2,'sa','auto','상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-1-u2-C1","difficulty":2,"kind":"sa","stem":"상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["상자 모양은 주사위·도시락이에요.","모두 2개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"},{"icon":"🥫","name":"통조림"},{"icon":"⚽","name":"축구공"},{"icon":"🍱","name":"도시락"},{"icon":"🔋","name":"건전지"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#15','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C3',2,'ox','auto','공 모양은 쌓을 수 있어요.',ARRAY['M1-1-u2-X08']::text[],true,'{"seq":15,"concept":"M1-1-u2-C3","difficulty":2,"kind":"ox","stem":"공 모양은 쌓을 수 있어요.","answer":"X","reason_options":[{"t":"평평한 부분이 없어 굴러떨어지니까","correct":true},{"t":"평평한 부분끼리 맞닿으니까","mis":"M1-1-u2-X08"}],"mis":"M1-1-u2-X08","explanation":["공 모양은 쌓을 수 없어요.","「쌓을 수 있어요」는 상자 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["rollall","stack"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#16','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C4',2,'mc','auto','만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":16,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u2-X11"},{"t":"3","mis":"M1-1-u2-X11"}],"explanation":["서 있는 기둥과 누운 기둥을 모두 세어요.","모두 4개예요.","누운 기둥도 기둥 모양이에요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":4},{"solid":"ball","n":2}],"name":"기차","lay":true},"variant_rule":{"solidart":{"ask":"cyl","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#17','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C1',3,'mc','auto','두 그림은 놓인 모습이 달라요. 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X03']::text[],false,'{"seq":17,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"두 그림은 놓인 모습이 달라요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"누운 것은 상자 모양이에요","mis":"M1-1-u2-X03"},{"t":"누운 것은 공 모양이에요","mis":"M1-1-u2-X03"}],"explanation":["누워 있어도 위·아래는 평평하고 옆은 둥글어요.","놓인 방향이 바뀌어도 모양은 그대로예요.","누운 것을 일으켜 세워 보세요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#18','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C2',3,'error','auto','주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?',ARRAY['M1-1-u2-X06','M1-1-u2-X04']::text[],false,'{"seq":18,"concept":"M1-1-u2-C2","difficulty":3,"kind":"error","stem":"주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「뾰족한 부분이 있어요.」","correct":true,"mis_target":"M1-1-u2-X06"},{"t":"「위와 아래가 평평해요.」","mis":"M1-1-u2-X06"},{"t":"「옆이 둥글어요.」","mis":"M1-1-u2-X04"}],"explanation":["기둥 모양은 뾰족한 부분이 없어요.","위·아래가 평평하고 옆이 둥근 것은 맞아요.","찔리는 곳이 있나 만져 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#19','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C3',3,'error','auto','친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X08']::text[],false,'{"seq":19,"concept":"M1-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「기둥 모양은 어떻게 놓아도 잘 굴러가.」","correct":true,"mis_target":"M1-1-u2-X07"},{"t":"「공 모양은 어느 쪽으로든 굴러가.」","mis":"M1-1-u2-X08"},{"t":"「상자 모양은 밀어도 굴러가지 않아.」","mis":"M1-1-u2-X08"}],"explanation":["기둥 모양은 세워 두면 굴러가지 않아요.","눕혀야 한 방향으로 굴러가요.","놓는 방향을 바꿔 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#20','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C4',3,'error','auto','친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u2-X11']::text[],false,'{"seq":20,"concept":"M1-1-u2-C4","difficulty":3,"kind":"error","stem":"친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「상자 모양을 2개 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「공 모양을 2개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「모두 7개를 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["상자 모양은 3개예요 — 하나를 빠뜨렸어요.","공 2개, 모두 7개는 맞아요.","모양마다 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":2},{"solid":"ball","n":2}],"name":"성"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#21','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C5',3,'mc','auto','주머니 속 물건을 만졌더니 둥근 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":21,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"주머니 속 물건을 만졌더니 둥근 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"상자 모양은 아니에요","correct":true},{"t":"공 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["둥근 부분은 기둥에도 공에도 있어요.","상자가 아닌 것만 알 수 있어요.","단서가 모자라면 알 수 있는 것까지만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#22','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C5',3,'mc','auto','모양 맞히기 놀이에서 두 단서를 들었어요. 「쌓을 수 있어요.」 「굴러갈 수도 있어요.」 어떤 모양인가요?',ARRAY['M1-1-u2-X08']::text[],false,'{"seq":22,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「쌓을 수 있어요.」 「굴러갈 수도 있어요.」 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X08"},{"t":"공 모양","mis":"M1-1-u2-X08"}],"explanation":["쌓을 수 있는 것은 상자와 기둥이에요.","그 가운데 굴러갈 수도 있는 것은 기둥이에요.","단서를 하나씩 더하며 후보를 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#23','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C3',4,'mc','auto','주사위가 공 모양이라면 놀이할 때 어떤 일이 생길까요?',ARRAY['M1-1-u2-X08','M1-1-u2-X06']::text[],false,'{"seq":23,"concept":"M1-1-u2-C3","difficulty":4,"kind":"mc","stem":"주사위가 공 모양이라면 놀이할 때 어떤 일이 생길까요?","options":[{"t":"굴러가다 멈추지 않아 숫자를 읽기 어려워요","correct":true},{"t":"더 높이 쌓을 수 있어요","mis":"M1-1-u2-X08"},{"t":"모서리가 더 뾰족해져요","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 평평한 부분이 없어 잘 멈추지 않아요.","그래서 위쪽 숫자를 정하기 어려워요.","주사위가 상자 모양인 까닭을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#24','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C2',4,'mc','auto','다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?',ARRAY['M1-1-u2-X04']::text[],false,'{"seq":24,"concept":"M1-1-u2-C2","difficulty":4,"kind":"mc","stem":"다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"여러 방향으로 잘 굴러가요","correct":true},{"t":"둥근 부분이 있어요","mis":"M1-1-u2-X04"},{"t":"뾰족한 부분이 없어요","mis":"M1-1-u2-X04"}],"explanation":["여러 방향으로 잘 굴러가는 것은 공 모양뿐이에요.","둥근 부분·뾰족한 곳 없음은 기둥에도 맞아요.","다른 두 모양에도 대 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_a#25','math',1,1,'u2','','g1_1_math_u2_review_a','unit_review','M1-1-u2-C4',4,'essay','teacher','상자·기둥·공 모양을 하나 이상씩 써서 놀이터 기구를 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u2-C4","difficulty":4,"kind":"essay","stem":"상자·기둥·공 모양을 하나 이상씩 써서 놀이터 기구를 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 시소를 만들어요. 앉는 자리는 상자 모양 — 평평해서 앉기 좋아요. 가운데 받침은 세운 기둥 — 위가 평평해 판을 받쳐요. 손잡이 끝은 공 모양 — 둥글어서 다치지 않아요.","scoring_points":["세 모양을 모두 썼는가","모양마다 쓸 자리를 말했는가","평평하다·굴러간다·둥글다 같은 특징으로 까닭을 댔는가"]},"explanation":["만들 것을 먼저 정해요.","자리마다 필요한 특징을 떠올려요.","그 특징이 있는 모양을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#1','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C1',1,'mc','auto','두루마리 휴지는 어떤 모양인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X05']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"두루마리 휴지는 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X04"},{"t":"상자 모양","mis":"M1-1-u2-X05"}],"explanation":["위·아래는 평평하고 옆은 둥글어요.","그래서 기둥 모양이에요.","둥근 곳이 있다고 다 공 모양은 아니에요."],"asset":{"type":"solid_row","items":[{"icon":"🧻","name":"두루마리 휴지"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#2','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C1',1,'match','auto','물건과 같은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":1,"kind":"match","stem":"물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"도시락","r":"상자 모양"},{"l":"통조림","r":"기둥 모양"},{"l":"수박","r":"공 모양"}],"mis":"M1-1-u2-X02","explanation":["도시락은 상자, 통조림은 기둥, 수박은 공 모양이에요.","수박은 이름에 「공」이 없어도 공 모양이에요.","생김새로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#3','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C2',1,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#4','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C3',1,'mc','auto','여러 방향으로 잘 굴러가는 모양은 무엇인가요?',ARRAY['M1-1-u2-X09','M1-1-u2-X08']::text[],false,'{"seq":4,"concept":"M1-1-u2-C3","difficulty":1,"kind":"mc","stem":"여러 방향으로 잘 굴러가는 모양은 무엇인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X09"},{"t":"상자 모양","mis":"M1-1-u2-X08"}],"explanation":["공 모양은 어느 쪽이든 둥근 부분이 바닥에 닿아요.","그래서 여러 방향으로 굴러가요.","기둥은 한 방향으로만 굴러가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#5','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C4',1,'sa','auto','만드는 데 쓴 공 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u2-C4","difficulty":1,"kind":"sa","stem":"만드는 데 쓴 공 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["공 모양만 골라 세어요.","모두 4개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":1},{"solid":"ball","n":4}],"name":"애벌레"},"variant_rule":{"solidart":{"ask":"ball","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#6','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C5',1,'mc','auto','얼음과 벽돌의 같은 점은 무엇인가요?',ARRAY['M1-1-u2-X12']::text[],false,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"얼음과 벽돌의 같은 점은 무엇인가요?","options":[{"t":"둘 다 상자 모양이에요","correct":true},{"t":"둘 다 차가워요","mis":"M1-1-u2-X12"},{"t":"둘 다 색깔이 같아요","mis":"M1-1-u2-X12"}],"explanation":["둘 다 평평한 부분과 뾰족한 부분이 있어요.","차갑다·색깔은 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#7','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C1',1,'blank','auto','구슬, 농구공, 수박은 모두 (        ) 모양이에요.',ARRAY['M1-1-u2-X04','M1-1-u2-X02']::text[],false,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":1,"kind":"blank","stem":"구슬, 농구공, 수박은 모두 (        ) 모양이에요.","options":[{"t":"공","correct":true},{"t":"기둥","mis":"M1-1-u2-X04"},{"t":"상자","mis":"M1-1-u2-X02"}],"explanation":["셋 다 둥근 부분만 있어요.","모두 공 모양이에요.","이름에 「공」이 없어도 같은 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#8','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C2',1,'ox','auto','기둥 모양은 둥근 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":8,"concept":"M1-1-u2-C2","difficulty":1,"kind":"ox","stem":"기둥 모양은 둥근 부분이 있어요.","answer":"O","reason_options":[{"t":"옆이 둥그니까","correct":true},{"t":"평평한 부분과 뾰족한 부분만 있으니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["기둥 모양은 둥근 부분이 있어요.","「둥근 부분이 있어요」는 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["flat","corner","round"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#9','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C5',2,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X12','M1-1-u2-X01']::text[],true,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"택배 상자","correct":true},{"t":"북","mis":"M1-1-u2-X12"},{"t":"건전지","mis":"M1-1-u2-X01"}],"explanation":["북·건전지·통나무는 기둥 모양이에요.","택배 상자만 상자 모양이에요.","둥근 곳이 있는지 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"📦","name":"택배 상자"},{"icon":"🥁","name":"북"},{"icon":"🔋","name":"건전지"},{"icon":"🪵","name":"통나무"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#10','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C2',2,'mc','auto','그림의 모양에 있는 부분을 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X06']::text[],false,'{"seq":10,"concept":"M1-1-u2-C2","difficulty":2,"kind":"mc","stem":"그림의 모양에 있는 부분을 바르게 말한 것은 어느 것인가요?","options":[{"t":"평평한 부분과 뾰족한 부분","correct":true},{"t":"평평한 부분과 둥근 부분","mis":"M1-1-u2-X04"},{"t":"둥근 부분만","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 평평한 부분과 뾰족한 부분이 있어요.","둥근 부분은 없어요.","모서리 끝을 짚어 보세요."],"asset":{"type":"solid_row","items":["box"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#11','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C3',2,'mc','auto','두 기둥 위에 책을 올리려고 해요. 올리기 좋은 것은 어느 것인가요?',ARRAY['M1-1-u2-X07']::text[],false,'{"seq":11,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"두 기둥 위에 책을 올리려고 해요. 올리기 좋은 것은 어느 것인가요?","options":[{"t":"① 선 기둥","correct":true},{"t":"② 누운 기둥","mis":"M1-1-u2-X07"},{"t":"둘 다 올릴 수 없어요","mis":"M1-1-u2-X07"}],"explanation":["선 기둥은 위가 평평해 올릴 수 있어요.","누운 기둥은 둥근 옆 때문에 미끄러져요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl","cyl_lay"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#12','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C4',2,'mc','auto','인형 의자의 앉는 자리로 어울리는 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X07']::text[],false,'{"seq":12,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"인형 의자의 앉는 자리로 어울리는 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["앉는 자리는 평평하고 멈춰 있어야 해요.","상자 모양이 어울려요.","그 자리가 멈춰 있어야 하는지 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#13','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X13','M1-1-u2-X05']::text[],false,'{"seq":13,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X05"}],"explanation":["위는 평평한 동그라미, 옆은 둥글어요.","평평한 곳과 둥근 곳이 함께 있으면 기둥 모양이에요.","보이는 부분의 단서를 모두 써요."],"asset":{"type":"solid_row","items":[{"solid":"cyl","peek":true}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#14','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C1',2,'sa','auto','기둥 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-1-u2-C1","difficulty":2,"kind":"sa","stem":"기둥 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["기둥 모양은 북·통나무·두루마리 휴지예요.","모두 3개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🥁","name":"북"},{"icon":"🎁","name":"선물 상자"},{"icon":"🪵","name":"통나무"},{"icon":"🔮","name":"구슬"},{"icon":"🧻","name":"두루마리 휴지"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#15','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C3',2,'ox','auto','기둥 모양은 여러 방향으로 잘 굴러가요.',ARRAY['M1-1-u2-X09']::text[],true,'{"seq":15,"concept":"M1-1-u2-C3","difficulty":2,"kind":"ox","stem":"기둥 모양은 여러 방향으로 잘 굴러가요.","answer":"X","reason_options":[{"t":"눕히면 한 방향으로만 굴러가니까","correct":true},{"t":"어느 쪽으로 밀어도 둥근 부분이 바닥에 닿으니까","mis":"M1-1-u2-X09"}],"mis":"M1-1-u2-X09","explanation":["기둥 모양은 여러 방향으로 굴러가지 않아요.","「여러 방향으로 잘 굴러가요」는 공 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["rollall","stack"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#16','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C4',2,'mc','auto','만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":16,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.","options":[{"t":"5","correct":true},{"t":"3","mis":"M1-1-u2-X11"},{"t":"4","mis":"M1-1-u2-X11"}],"explanation":["서 있는 기둥과 누운 기둥을 모두 세어요.","모두 5개예요.","누운 기둥도 기둥 모양이에요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":5},{"solid":"ball","n":1}],"name":"다리","lay":true},"variant_rule":{"solidart":{"ask":"cyl","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#17','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C1',3,'mc','auto','건전지가 누워 있어요. 건전지는 어떤 모양인가요?',ARRAY['M1-1-u2-X03','M1-1-u2-X04']::text[],false,'{"seq":17,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"건전지가 누워 있어요. 건전지는 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X03"},{"t":"공 모양","mis":"M1-1-u2-X04"}],"explanation":["건전지는 양 끝이 평평하고 옆이 둥글어요.","누워 있어도 기둥 모양이에요.","세워 놓았다고 생각해 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🔋","name":"건전지"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#18','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C2',3,'error','auto','주원이가 공 모양을 설명했어요. 잘못된 것은 어느 것인가요?',ARRAY['M1-1-u2-X06']::text[],false,'{"seq":18,"concept":"M1-1-u2-C2","difficulty":3,"kind":"error","stem":"주원이가 공 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「평평한 부분이 조금 있어요.」","correct":true,"mis_target":"M1-1-u2-X06"},{"t":"「둥근 부분만 있어요.」","mis":"M1-1-u2-X06"},{"t":"「뾰족한 부분이 없어요.」","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 평평한 부분이 없어요.","둥근 부분만 있고 뾰족한 곳도 없어요.","어디를 놓아도 굴러가는 까닭을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#19','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C3',3,'error','auto','친구들이 모양을 쌓아 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X07']::text[],false,'{"seq":19,"concept":"M1-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 모양을 쌓아 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「공 모양도 조심하면 높이 쌓을 수 있어.」","correct":true,"mis_target":"M1-1-u2-X08"},{"t":"「상자 모양은 잘 쌓여.」","mis":"M1-1-u2-X08"},{"t":"「기둥 모양은 세우면 쌓을 수 있어.」","mis":"M1-1-u2-X07"}],"explanation":["공 모양은 평평한 부분이 없어 쌓을 수 없어요.","상자와 세운 기둥은 쌓을 수 있어요.","평평한 곳끼리 맞닿아야 쌓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#20','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C4',3,'error','auto','친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u2-X11']::text[],false,'{"seq":20,"concept":"M1-1-u2-C4","difficulty":3,"kind":"error","stem":"친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「기둥 모양을 2개 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「상자 모양을 2개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「공 모양을 1개 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["기둥 모양은 4개예요 — 누운 기둥을 빠뜨렸어요.","누운 기둥도 기둥 모양이에요.","모양마다 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":4},{"solid":"ball","n":1}],"name":"기차","lay":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#21','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C5',3,'mc','auto','주머니 속 물건을 만졌더니 평평한 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":21,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"주머니 속 물건을 만졌더니 평평한 부분이 만져졌어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"공 모양은 아니에요","correct":true},{"t":"상자 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["평평한 부분은 상자에도 기둥에도 있어요.","공이 아닌 것만 알 수 있어요.","단서가 모자라면 알 수 있는 것까지만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#22','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C5',3,'mc','auto','모양 맞히기 놀이에서 두 단서를 들었어요. 「뾰족한 부분이 없어요.」 「쌓을 수 없어요.」 어떤 모양인가요?',ARRAY['M1-1-u2-X13','M1-1-u2-X06']::text[],false,'{"seq":22,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「뾰족한 부분이 없어요.」 「쌓을 수 없어요.」 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X06"}],"explanation":["뾰족한 부분이 없는 것은 기둥과 공이에요.","그 가운데 쌓을 수 없는 것은 공이에요.","단서를 하나씩 더하며 후보를 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#23','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C3',4,'mc','auto','자동차 바퀴가 상자 모양이라면 어떤 일이 생길까요?',ARRAY['M1-1-u2-X08','M1-1-u2-X06']::text[],false,'{"seq":23,"concept":"M1-1-u2-C3","difficulty":4,"kind":"mc","stem":"자동차 바퀴가 상자 모양이라면 어떤 일이 생길까요?","options":[{"t":"굴러가지 않아 자동차가 잘 움직이지 못해요","correct":true},{"t":"여러 방향으로 더 잘 굴러가요","mis":"M1-1-u2-X08"},{"t":"바퀴가 둥글어져요","mis":"M1-1-u2-X06"}],"explanation":["상자 모양은 평평해서 굴러가지 않아요.","그래서 바퀴로 쓰기 어려워요.","바퀴가 기둥 모양인 까닭을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#24','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C2',4,'mc','auto','다음 가운데 상자 모양에만 맞는 설명은 어느 것인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X07']::text[],false,'{"seq":24,"concept":"M1-1-u2-C2","difficulty":4,"kind":"mc","stem":"다음 가운데 상자 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"뾰족한 부분이 있어요","correct":true},{"t":"평평한 부분이 있어요","mis":"M1-1-u2-X05"},{"t":"쌓을 수 있어요","mis":"M1-1-u2-X07"}],"explanation":["뾰족한 부분은 상자 모양에만 있어요.","평평한 부분·쌓기는 기둥에도 맞아요.","다른 두 모양에도 대 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_b#25','math',1,1,'u2','','g1_1_math_u2_review_b','unit_review','M1-1-u2-C4',4,'essay','teacher','상자·기둥·공 모양을 하나 이상씩 써서 굴러가는 장난감을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u2-C4","difficulty":4,"kind":"essay","stem":"상자·기둥·공 모양을 하나 이상씩 써서 굴러가는 장난감을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 장난감 자동차를 만들어요. 몸통은 상자 모양 — 평평해서 짐을 실어요. 바퀴는 눕힌 기둥 — 한 방향으로 굴러가요. 전조등은 공 모양 — 둥글어서 불빛처럼 보여요.","scoring_points":["세 모양을 모두 썼는가","모양마다 쓸 자리를 말했는가","평평하다·굴러간다·둥글다 같은 특징으로 까닭을 댔는가"]},"explanation":["만들 것을 먼저 정해요.","굴러가야 하는 자리를 찾아요.","그 특징이 있는 모양을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#1','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C1',1,'mc','auto','테니스공은 어떤 모양인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X02']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"테니스공은 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X04"},{"t":"상자 모양","mis":"M1-1-u2-X02"}],"explanation":["어디를 보아도 둥글어요.","그래서 공 모양이에요.","평평한 곳이 하나도 없어요."],"asset":{"type":"solid_row","items":[{"icon":"🎾","name":"테니스공"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#2','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C1',1,'match','auto','물건과 같은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":1,"kind":"match","stem":"물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"얼음","r":"상자 모양"},{"l":"건전지","r":"기둥 모양"},{"l":"배구공","r":"공 모양"}],"mis":"M1-1-u2-X02","explanation":["얼음은 상자, 건전지는 기둥, 배구공은 공 모양이에요.","건전지는 누워 있어도 기둥 모양이에요.","생김새로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
