INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#4','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C3',1,'mc','auto','쌓을 수 없는 모양은 무엇인가요?',ARRAY['M1-1-u2-X08','M1-1-u2-X07']::text[],false,'{"seq":4,"concept":"M1-1-u2-C3","difficulty":1,"kind":"mc","stem":"쌓을 수 없는 모양은 무엇인가요?","options":[{"t":"공 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X08"},{"t":"기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["공 모양은 평평한 부분이 없어요.","위에 올리면 굴러떨어져요.","상자와 세운 기둥은 쌓을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
