INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#6','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C5',1,'mc','auto','테니스공과 수박의 같은 점은 무엇인가요?',ARRAY['M1-1-u2-X12','M1-1-u2-X01']::text[],false,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"테니스공과 수박의 같은 점은 무엇인가요?","options":[{"t":"둘 다 공 모양이에요","correct":true},{"t":"둘 다 먹을 수 있어요","mis":"M1-1-u2-X12"},{"t":"둘 다 크기가 같아요","mis":"M1-1-u2-X01"}],"explanation":["둘 다 둥근 부분만 있어요.","쓰임·크기는 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#7','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C1',1,'blank','auto','통조림, 북, 통나무는 모두 (        ) 모양이에요.',ARRAY['M1-1-u2-X04','M1-1-u2-X05']::text[],false,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":1,"kind":"blank","stem":"통조림, 북, 통나무는 모두 (        ) 모양이에요.","options":[{"t":"기둥","correct":true},{"t":"공","mis":"M1-1-u2-X04"},{"t":"상자","mis":"M1-1-u2-X05"}],"explanation":["셋 다 평평한 부분과 둥근 옆이 있어요.","모두 기둥 모양이에요.","누워 있어도 같은 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#8','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C2',1,'ox','auto','상자 모양은 평평한 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":8,"concept":"M1-1-u2-C2","difficulty":1,"kind":"ox","stem":"상자 모양은 평평한 부분이 있어요.","answer":"O","reason_options":[{"t":"평평한 부분으로 둘러싸여 있으니까","correct":true},{"t":"어디를 만져도 둥글기만 하니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["상자 모양은 평평한 부분이 있어요.","「평평한 부분이 있어요」는 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["flat","corner","round"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#9','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C5',2,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X12']::text[],true,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"테니스공","correct":true},{"t":"주사위","mis":"M1-1-u2-X01"},{"t":"얼음","mis":"M1-1-u2-X12"}],"explanation":["주사위·얼음·벽돌은 상자 모양이에요.","테니스공만 공 모양이에요.","뾰족한 곳이 있는지 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🎲","name":"주사위"},{"icon":"🧊","name":"얼음"},{"icon":"🧱","name":"벽돌"},{"icon":"🎾","name":"테니스공"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#10','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C2',2,'mc','auto','그림의 모양에 있는 부분을 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X06']::text[],false,'{"seq":10,"concept":"M1-1-u2-C2","difficulty":2,"kind":"mc","stem":"그림의 모양에 있는 부분을 바르게 말한 것은 어느 것인가요?","options":[{"t":"둥근 부분만","correct":true},{"t":"평평한 부분과 둥근 부분","mis":"M1-1-u2-X06"},{"t":"뾰족한 부분","mis":"M1-1-u2-X06"}],"explanation":["공 모양은 둥근 부분만 있어요.","평평한 곳도 뾰족한 곳도 없어요.","손바닥을 대 보면 판판한 곳이 없어요."],"asset":{"type":"solid_row","items":["ball"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#11','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C3',2,'mc','auto','두 기둥을 밀었어요. 굴러가지 않는 것은 어느 것인가요?',ARRAY['M1-1-u2-X07']::text[],false,'{"seq":11,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"두 기둥을 밀었어요. 굴러가지 않는 것은 어느 것인가요?","options":[{"t":"② 선 기둥","correct":true},{"t":"① 누운 기둥","mis":"M1-1-u2-X07"},{"t":"둘 다 굴러가지 않아요","mis":"M1-1-u2-X07"}],"explanation":["선 기둥은 평평한 아래가 바닥에 닿아 굴러가지 않아요.","누운 기둥은 둥근 옆으로 굴러가요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl_lay","cyl"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#12','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C4',2,'mc','auto','공이 굴러 나가지 않게 막는 울타리로 어울리는 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X07']::text[],false,'{"seq":12,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"공이 굴러 나가지 않게 막는 울타리로 어울리는 모양은 무엇인가요?","options":[{"t":"상자 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X10"},{"t":"누운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["울타리는 밀려도 굴러가지 않아야 해요.","상자 모양은 굴러가지 않아요.","그 자리가 멈춰 있어야 하는지 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#13','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":13,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"공 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X13"}],"explanation":["보이는 곳이 모두 둥글고 평평한 곳이 없어요.","둥근 지붕처럼 생긴 것은 공 모양이에요.","보이는 부분에서 확실한 단서를 찾아요."],"asset":{"type":"solid_row","items":[{"solid":"ball","peek":true}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#14','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C1',2,'sa','auto','공 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-1-u2-C1","difficulty":2,"kind":"sa","stem":"공 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["공 모양은 농구공·테니스공·당구공이에요.","모두 3개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"🏀","name":"농구공"},{"icon":"🧊","name":"얼음"},{"icon":"🎾","name":"테니스공"},{"icon":"🥫","name":"통조림"},{"icon":"🎱","name":"당구공"},{"icon":"🧱","name":"벽돌"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#15','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C3',2,'ox','auto','상자 모양은 쌓을 수 있어요.',ARRAY['M1-1-u2-X08']::text[],true,'{"seq":15,"concept":"M1-1-u2-C3","difficulty":2,"kind":"ox","stem":"상자 모양은 쌓을 수 있어요.","answer":"O","reason_options":[{"t":"평평한 부분끼리 맞닿으니까","correct":true},{"t":"평평한 부분이 없어 굴러떨어지니까","mis":"M1-1-u2-X08"}],"mis":"M1-1-u2-X08","explanation":["상자 모양은 쌓을 수 있어요.","「쌓을 수 있어요」는 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["rollall","stack"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#16','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C4',2,'mc','auto','만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":16,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.","options":[{"t":"3","correct":true},{"t":"2","mis":"M1-1-u2-X11"},{"t":"4","mis":"M1-1-u2-X11"}],"explanation":["서 있는 기둥과 누운 기둥을 모두 세어요.","모두 3개예요.","누운 기둥도 기둥 모양이에요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":4},{"solid":"cyl","n":3},{"solid":"ball","n":2}],"name":"배","lay":true},"variant_rule":{"solidart":{"ask":"cyl","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#17','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C1',3,'mc','auto','같은 필통이라도 생김새가 다를 수 있어요. 기둥 모양 필통은 어느 것인가요?',ARRAY['M1-1-u2-X02']::text[],false,'{"seq":17,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"같은 필통이라도 생김새가 다를 수 있어요. 기둥 모양 필통은 어느 것인가요?","options":[{"t":"②","correct":true},{"t":"①","mis":"M1-1-u2-X02"},{"t":"둘 다 상자 모양이에요","mis":"M1-1-u2-X02"}],"explanation":["②는 위·아래가 평평하고 옆이 둥근 기둥 모양이에요.","「필통은 다 상자 모양」이 아니에요.","이름이 아니라 생김새로 나눠요."],"asset":{"type":"solid_row","items":["box","cyl"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#18','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C2',3,'error','auto','주원이가 상자 모양을 설명했어요. 잘못된 것은 어느 것인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X06']::text[],false,'{"seq":18,"concept":"M1-1-u2-C2","difficulty":3,"kind":"error","stem":"주원이가 상자 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「둥근 부분이 있어요.」","correct":true,"mis_target":"M1-1-u2-X04"},{"t":"「평평한 부분이 있어요.」","mis":"M1-1-u2-X06"},{"t":"「뾰족한 부분이 있어요.」","mis":"M1-1-u2-X06"}],"explanation":["상자 모양에는 둥근 부분이 없어요.","평평한 부분과 뾰족한 부분만 있어요.","둥근 곳이 있는 것은 기둥과 공이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#19','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C3',3,'error','auto','친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X09','M1-1-u2-X08']::text[],false,'{"seq":19,"concept":"M1-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 모양을 굴려 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「눕힌 기둥도 공처럼 여러 방향으로 굴러가.」","correct":true,"mis_target":"M1-1-u2-X09"},{"t":"「공 모양은 여러 방향으로 굴러가.」","mis":"M1-1-u2-X08"},{"t":"「상자 모양은 굴러가지 않아.」","mis":"M1-1-u2-X08"}],"explanation":["눕힌 기둥은 한 방향으로만 굴러가요.","여러 방향으로 굴러가는 것은 공 모양이에요.","굴러간 자국을 떠올려 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#20','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C4',3,'error','auto','친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u2-X11']::text[],false,'{"seq":20,"concept":"M1-1-u2-C4","difficulty":3,"kind":"error","stem":"친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「모두 9개를 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「상자 모양을 3개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「기둥 모양을 2개 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["3 + 2 + 3 = 8, 모두 8개예요.","하나를 두 번 센 셈이에요.","센 모양에 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":3},{"solid":"cyl","n":2},{"solid":"ball","n":3}],"name":"로봇"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#21','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C5',3,'mc','auto','주머니 속 물건을 만졌더니 뾰족한 부분은 없었어요. 이것만으로 알 수 있는 것은 무엇인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":21,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"주머니 속 물건을 만졌더니 뾰족한 부분은 없었어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"상자 모양은 아니에요","correct":true},{"t":"공 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["뾰족한 부분이 없는 것은 기둥과 공이에요.","상자가 아닌 것만 알 수 있어요.","단서가 모자라면 알 수 있는 것까지만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#22','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C5',3,'mc','auto','모양 맞히기 놀이에서 두 단서를 들었어요. 「평평한 부분이 있어요.」 「굴러가지 않아요.」 어떤 모양인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X06']::text[],false,'{"seq":22,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「평평한 부분이 있어요.」 「굴러가지 않아요.」 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X07"},{"t":"공 모양","mis":"M1-1-u2-X06"}],"explanation":["평평한 부분이 있는 것은 상자와 기둥이에요.","그 가운데 어떻게 놓아도 굴러가지 않는 것은 상자예요.","단서를 하나씩 더하며 후보를 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#23','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C3',4,'mc','auto','쌓기나무가 공 모양이라면 어떤 일이 생길까요?',ARRAY['M1-1-u2-X08','M1-1-u2-X09']::text[],false,'{"seq":23,"concept":"M1-1-u2-C3","difficulty":4,"kind":"mc","stem":"쌓기나무가 공 모양이라면 어떤 일이 생길까요?","options":[{"t":"위에 올리면 굴러떨어져 쌓을 수 없어요","correct":true},{"t":"더 높이 쌓을 수 있어요","mis":"M1-1-u2-X08"},{"t":"한 방향으로만 굴러가요","mis":"M1-1-u2-X09"}],"explanation":["공 모양은 평평한 부분이 없어요.","그래서 쌓을 수 없어요.","쌓기나무가 상자 모양인 까닭을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#24','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C2',4,'mc','auto','다음 가운데 기둥 모양에만 맞는 설명은 어느 것인가요?',ARRAY['M1-1-u2-X04','M1-1-u2-X05']::text[],false,'{"seq":24,"concept":"M1-1-u2-C2","difficulty":4,"kind":"mc","stem":"다음 가운데 기둥 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"평평한 부분과 둥근 부분이 함께 있어요","correct":true},{"t":"둥근 부분이 있어요","mis":"M1-1-u2-X04"},{"t":"평평한 부분이 있어요","mis":"M1-1-u2-X05"}],"explanation":["평평한 부분과 둥근 부분이 함께 있는 것은 기둥뿐이에요.","둥근 부분은 공, 평평한 부분은 상자에도 있어요.","다른 두 모양에도 대 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_c#25','math',1,1,'u2','','g1_1_math_u2_review_c','unit_review','M1-1-u2-C4',4,'essay','teacher','상자·기둥·공 모양을 하나 이상씩 써서 우리 교실에 있는 물건을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u2-C4","difficulty":4,"kind":"essay","stem":"상자·기둥·공 모양을 하나 이상씩 써서 우리 교실에 있는 물건을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 책상을 만들어요. 상판은 상자 모양 — 평평해서 공책을 놓아요. 다리는 세운 기둥 — 위가 평평해 상판을 받쳐요. 서랍 손잡이는 공 모양 — 둥글어서 잡기 좋아요.","scoring_points":["세 모양을 모두 썼는가","모양마다 쓸 자리를 말했는가","평평하다·굴러간다·둥글다 같은 특징으로 까닭을 댔는가"]},"explanation":["만들 것을 먼저 정해요.","자리마다 필요한 특징을 떠올려요.","그 특징이 있는 모양을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#1','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C1',1,'mc','auto','벽돌은 어떤 모양인가요?',ARRAY['M1-1-u2-X02']::text[],true,'{"seq":1,"concept":"M1-1-u2-C1","difficulty":1,"kind":"mc","stem":"벽돌은 어떤 모양인가요?","options":[{"t":"상자 모양","correct":true},{"t":"기둥 모양","mis":"M1-1-u2-X02"},{"t":"공 모양","mis":"M1-1-u2-X02"}],"explanation":["평평한 부분과 뾰족한 부분이 있어요.","그래서 상자 모양이에요.","이름이 아니라 생김새를 보고 나눠요."],"asset":{"type":"solid_row","items":[{"icon":"🧱","name":"벽돌"}]},"variant_rule":{"solids":{"ask":"which"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#2','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C1',1,'match','auto','물건과 같은 모양을 줄로 이어 보세요.','{}'::text[],false,'{"seq":2,"concept":"M1-1-u2-C1","difficulty":1,"kind":"match","stem":"물건과 같은 모양을 줄로 이어 보세요.","pairs":[{"l":"택배 상자","r":"상자 모양"},{"l":"통나무","r":"기둥 모양"},{"l":"당구공","r":"공 모양"}],"mis":"M1-1-u2-X02","explanation":["택배 상자는 상자, 통나무는 기둥, 당구공은 공 모양이에요.","통나무는 누워 있어도 기둥 모양이에요.","생김새로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#3','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C2',1,'mc','auto','다음 설명에 알맞은 모양은 무엇인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#4','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C3',1,'mc','auto','세우면 쌓을 수 있고 눕히면 굴러가는 모양은 무엇인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X08']::text[],false,'{"seq":4,"concept":"M1-1-u2-C3","difficulty":1,"kind":"mc","stem":"세우면 쌓을 수 있고 눕히면 굴러가는 모양은 무엇인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X07"},{"t":"공 모양","mis":"M1-1-u2-X08"}],"explanation":["세우면 평평한 부분끼리 맞닿아요.","눕히면 둥근 옆으로 굴러가요.","두 가지를 다 하는 것은 기둥뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#5','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C4',1,'sa','auto','만드는 데 쓴 상자 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M1-1-u2-C4","difficulty":1,"kind":"sa","stem":"만드는 데 쓴 상자 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["상자 모양만 골라 세어요.","모두 5개예요.","센 모양에 하나씩 표시하면 빠뜨리지 않아요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":5},{"solid":"cyl","n":1},{"solid":"ball","n":2}],"name":"집"},"variant_rule":{"solidart":{"ask":"box","n":[1,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#6','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C5',1,'mc','auto','통나무와 두루마리 휴지의 같은 점은 무엇인가요?',ARRAY['M1-1-u2-X12','M1-1-u2-X03']::text[],false,'{"seq":6,"concept":"M1-1-u2-C5","difficulty":1,"kind":"mc","stem":"통나무와 두루마리 휴지의 같은 점은 무엇인가요?","options":[{"t":"둘 다 기둥 모양이에요","correct":true},{"t":"둘 다 나무로 만들어요","mis":"M1-1-u2-X12"},{"t":"둘 다 누워 있어요","mis":"M1-1-u2-X03"}],"explanation":["둘 다 양 끝이 평평하고 옆이 둥글어요.","재료·놓인 방향은 모양의 같은 점이 아니에요.","생김새로만 말해 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#7','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C1',1,'blank','auto','택배 상자, 벽돌, 선물 상자는 모두 (        ) 모양이에요.',ARRAY['M1-1-u2-X05','M1-1-u2-X02']::text[],false,'{"seq":7,"concept":"M1-1-u2-C1","difficulty":1,"kind":"blank","stem":"택배 상자, 벽돌, 선물 상자는 모두 (        ) 모양이에요.","options":[{"t":"상자","correct":true},{"t":"기둥","mis":"M1-1-u2-X05"},{"t":"공","mis":"M1-1-u2-X02"}],"explanation":["셋 다 평평한 부분과 뾰족한 부분이 있어요.","모두 상자 모양이에요.","크기가 달라도 같은 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#8','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C2',1,'ox','auto','기둥 모양은 뾰족한 부분이 있어요.',ARRAY['M1-1-u2-X06']::text[],true,'{"seq":8,"concept":"M1-1-u2-C2","difficulty":1,"kind":"ox","stem":"기둥 모양은 뾰족한 부분이 있어요.","answer":"X","reason_options":[{"t":"평평한 부분과 둥근 부분만 있으니까","correct":true},{"t":"모서리 끝이 뾰족하니까","mis":"M1-1-u2-X06"}],"mis":"M1-1-u2-X06","explanation":["기둥 모양은 뾰족한 부분이 없어요.","「뾰족한 부분이 있어요」는 상자 모양에 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["flat","corner","round"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#9','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C5',2,'mc','auto','모양이 다른 하나는 무엇인가요?',ARRAY['M1-1-u2-X01','M1-1-u2-X12']::text[],true,'{"seq":9,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"모양이 다른 하나는 무엇인가요?","options":[{"t":"두루마리 휴지","correct":true},{"t":"배구공","mis":"M1-1-u2-X01"},{"t":"농구공","mis":"M1-1-u2-X12"}],"explanation":["배구공·농구공·구슬은 공 모양이에요.","두루마리 휴지만 기둥 모양이에요.","평평한 곳이 있는지 견주어요."],"asset":{"type":"solid_row","items":[{"icon":"🧻","name":"두루마리 휴지"},{"icon":"🏐","name":"배구공"},{"icon":"🏀","name":"농구공"},{"icon":"🔮","name":"구슬"}],"num":true},"variant_rule":{"solids":{"ask":"odd"}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#10','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C2',2,'mc','auto','누운 그림의 모양에서 평평한 부분은 어디인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X03']::text[],false,'{"seq":10,"concept":"M1-1-u2-C2","difficulty":2,"kind":"mc","stem":"누운 그림의 모양에서 평평한 부분은 어디인가요?","options":[{"t":"양쪽 끝","correct":true},{"t":"둥근 옆","mis":"M1-1-u2-X05"},{"t":"평평한 부분이 없어요","mis":"M1-1-u2-X03"}],"explanation":["누운 기둥은 양쪽 끝이 평평해요.","옆은 둥근 부분이에요 — 누워도 기둥이에요.","세워 놓았다고 생각해 보세요."],"asset":{"type":"solid_row","items":["cyl_lay"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#11','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C3',2,'mc','auto','두 기둥을 쌓으려고 해요. 쌓기 좋게 놓은 것은 어느 것인가요?',ARRAY['M1-1-u2-X07']::text[],false,'{"seq":11,"concept":"M1-1-u2-C3","difficulty":2,"kind":"mc","stem":"두 기둥을 쌓으려고 해요. 쌓기 좋게 놓은 것은 어느 것인가요?","options":[{"t":"② 선 기둥","correct":true},{"t":"① 누운 기둥","mis":"M1-1-u2-X07"},{"t":"어떻게 놓아도 똑같아요","mis":"M1-1-u2-X07"}],"explanation":["선 기둥은 평평한 부분끼리 맞닿아 쌓여요.","누운 기둥은 둥근 옆 때문에 굴러떨어져요.","같은 기둥도 놓는 방향에 따라 달라요."],"asset":{"type":"solid_row","items":["cyl_lay","cyl"],"num":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#12','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C4',2,'mc','auto','볼링 놀이에서 굴려서 핀을 쓰러뜨릴 것으로 어울리는 모양은 무엇인가요?',ARRAY['M1-1-u2-X10','M1-1-u2-X07']::text[],false,'{"seq":12,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"볼링 놀이에서 굴려서 핀을 쓰러뜨릴 것으로 어울리는 모양은 무엇인가요?","options":[{"t":"공 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X10"},{"t":"세운 기둥 모양","mis":"M1-1-u2-X07"}],"explanation":["굴릴 것은 잘 굴러가야 해요.","공 모양은 어느 쪽으로든 잘 굴러가요.","그 자리가 굴러가야 하는지 먼저 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#13','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C5',2,'mc','auto','주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X13']::text[],false,'{"seq":13,"concept":"M1-1-u2-C5","difficulty":2,"kind":"mc","stem":"주머니 속 모양이 윗부분만 보여요. 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"상자 모양","mis":"M1-1-u2-X05"},{"t":"공 모양","mis":"M1-1-u2-X13"}],"explanation":["위는 평평한 동그라미, 옆은 둥글어요.","평평한 곳과 둥근 곳이 함께 있으면 기둥 모양이에요.","보이는 부분의 단서를 모두 써요."],"asset":{"type":"solid_row","items":[{"solid":"cyl","peek":true}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#14','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C1',2,'sa','auto','상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-1-u2-C1","difficulty":2,"kind":"sa","stem":"상자 모양인 물건은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["상자 모양은 택배 상자·벽돌·얼음이에요.","모두 3개예요.","센 물건에 표시하면 두 번 세지 않아요."],"asset":{"type":"solid_row","items":[{"icon":"📦","name":"택배 상자"},{"icon":"🏐","name":"배구공"},{"icon":"🧱","name":"벽돌"},{"icon":"🥁","name":"북"},{"icon":"🧊","name":"얼음"},{"icon":"🔋","name":"건전지"}]},"variant_rule":{"solids":{"ask":"count","len":[5,6]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#15','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C3',2,'ox','auto','공 모양은 여러 방향으로 잘 굴러가요.',ARRAY['M1-1-u2-X09']::text[],true,'{"seq":15,"concept":"M1-1-u2-C3","difficulty":2,"kind":"ox","stem":"공 모양은 여러 방향으로 잘 굴러가요.","answer":"O","reason_options":[{"t":"어느 쪽으로 밀어도 둥근 부분이 바닥에 닿으니까","correct":true},{"t":"눕히면 한 방향으로만 굴러가니까","mis":"M1-1-u2-X09"}],"mis":"M1-1-u2-X09","explanation":["공 모양은 여러 방향으로 잘 굴러가요.","「여러 방향으로 잘 굴러가요」는 맞는 말이에요.","세 모양을 하나씩 떠올려 견주어 보세요."],"variant_rule":{"trait":{"ask":"ox","attrs":["rollall","stack"]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#16','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C4',2,'mc','auto','만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.',ARRAY['M1-1-u2-X11']::text[],true,'{"seq":16,"concept":"M1-1-u2-C4","difficulty":2,"kind":"mc","stem":"만드는 데 쓴 기둥 모양은 몇 개인가요? 누운 기둥도 세어 보세요.","options":[{"t":"4","correct":true},{"t":"2","mis":"M1-1-u2-X11"},{"t":"5","mis":"M1-1-u2-X11"}],"explanation":["서 있는 기둥과 누운 기둥을 모두 세어요.","모두 4개예요.","누운 기둥도 기둥 모양이에요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":2},{"solid":"cyl","n":4},{"solid":"ball","n":3}],"name":"놀이 기구","lay":true},"variant_rule":{"solidart":{"ask":"cyl","n":[2,5]}}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#17','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C1',3,'mc','auto','통나무가 바닥에 누워 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X03','M1-1-u2-X04']::text[],false,'{"seq":17,"concept":"M1-1-u2-C1","difficulty":3,"kind":"mc","stem":"통나무가 바닥에 누워 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"누워 있어도 기둥 모양이에요","correct":true},{"t":"누워 있으니 상자 모양이에요","mis":"M1-1-u2-X03"},{"t":"둥근 곳이 있으니 공 모양이에요","mis":"M1-1-u2-X04"}],"explanation":["통나무는 양 끝이 평평하고 옆이 둥글어요.","놓인 방향이 바뀌어도 기둥 모양이에요.","평평한 곳이 있는지도 보세요."],"asset":{"type":"solid_row","items":[{"icon":"🪵","name":"통나무"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#18','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C2',3,'error','auto','주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?',ARRAY['M1-1-u2-X05','M1-1-u2-X04','M1-1-u2-X06']::text[],false,'{"seq":18,"concept":"M1-1-u2-C2","difficulty":3,"kind":"error","stem":"주원이가 기둥 모양을 설명했어요. 잘못된 것은 어느 것인가요?","options":[{"t":"「평평한 부분만 있어요.」","correct":true,"mis_target":"M1-1-u2-X05"},{"t":"「둥근 부분이 있어요.」","mis":"M1-1-u2-X04"},{"t":"「뾰족한 부분이 없어요.」","mis":"M1-1-u2-X06"}],"explanation":["기둥 모양은 옆이 둥글어요.","평평한 부분만 있는 것은 상자 모양이에요.","옆을 손으로 쓸어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#19','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C3',3,'error','auto','친구들이 모양을 쌓아 보고 말했어요. 잘못 말한 것은 어느 것인가요?',ARRAY['M1-1-u2-X07','M1-1-u2-X08']::text[],false,'{"seq":19,"concept":"M1-1-u2-C3","difficulty":3,"kind":"error","stem":"친구들이 모양을 쌓아 보고 말했어요. 잘못 말한 것은 어느 것인가요?","options":[{"t":"「눕힌 기둥 위에도 상자를 잘 올릴 수 있어.」","correct":true,"mis_target":"M1-1-u2-X07"},{"t":"「세운 기둥 위에는 상자를 올릴 수 있어.」","mis":"M1-1-u2-X07"},{"t":"「공 위에는 상자를 올리기 어려워.」","mis":"M1-1-u2-X08"}],"explanation":["눕힌 기둥은 위가 둥글어 올린 것이 미끄러져요.","세운 기둥 위는 평평해요.","같은 기둥도 놓는 방향에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#20','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C4',3,'error','auto','친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?',ARRAY['M1-1-u2-X11']::text[],false,'{"seq":20,"concept":"M1-1-u2-C4","difficulty":3,"kind":"error","stem":"친구가 만든 것을 보고 한 말이에요. 잘못된 말은 어느 것인가요?","options":[{"t":"「공 모양을 3개 썼어.」","correct":true,"mis_target":"M1-1-u2-X11"},{"t":"「상자 모양을 4개 썼어.」","mis":"M1-1-u2-X11"},{"t":"「기둥 모양을 3개 썼어.」","mis":"M1-1-u2-X11"}],"explanation":["공 모양은 2개예요 — 하나를 더 셌어요.","상자 4개, 기둥 3개는 맞아요.","모양마다 점을 찍으며 세어요."],"asset":{"type":"solid_art","parts":[{"solid":"box","n":4},{"solid":"cyl","n":3},{"solid":"ball","n":2}],"name":"집","lay":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#21','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C5',3,'mc','auto','물건을 바닥에 놓고 밀었더니 굴러갔어요. 이것만으로 알 수 있는 것은 무엇인가요?',ARRAY['M1-1-u2-X13']::text[],false,'{"seq":21,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"물건을 바닥에 놓고 밀었더니 굴러갔어요. 이것만으로 알 수 있는 것은 무엇인가요?","options":[{"t":"상자 모양은 아니에요","correct":true},{"t":"공 모양이에요","mis":"M1-1-u2-X13"},{"t":"기둥 모양이에요","mis":"M1-1-u2-X13"}],"explanation":["굴러가는 것은 눕힌 기둥과 공이에요.","상자가 아닌 것만 알 수 있어요.","단서가 모자라면 알 수 있는 것까지만 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#22','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C5',3,'mc','auto','모양 맞히기 놀이에서 두 단서를 들었어요. 「둥근 부분이 있어요.」 「평평한 부분도 있어요.」 어떤 모양인가요?',ARRAY['M1-1-u2-X13','M1-1-u2-X04']::text[],false,'{"seq":22,"concept":"M1-1-u2-C5","difficulty":3,"kind":"mc","stem":"모양 맞히기 놀이에서 두 단서를 들었어요. 「둥근 부분이 있어요.」 「평평한 부분도 있어요.」 어떤 모양인가요?","options":[{"t":"기둥 모양","correct":true},{"t":"공 모양","mis":"M1-1-u2-X13"},{"t":"상자 모양","mis":"M1-1-u2-X04"}],"explanation":["둥근 부분이 있는 것은 기둥과 공이에요.","그 가운데 평평한 부분도 있는 것은 기둥이에요.","단서를 하나씩 더하며 후보를 줄여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#23','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C3',4,'mc','auto','축구공이 기둥 모양이라면 어떤 일이 생길까요?',ARRAY['M1-1-u2-X09','M1-1-u2-X07']::text[],false,'{"seq":23,"concept":"M1-1-u2-C3","difficulty":4,"kind":"mc","stem":"축구공이 기둥 모양이라면 어떤 일이 생길까요?","options":[{"t":"한 방향으로만 굴러가 이리저리 차기 어려워요","correct":true},{"t":"어느 쪽으로든 더 잘 굴러가요","mis":"M1-1-u2-X09"},{"t":"전혀 굴러가지 않아요","mis":"M1-1-u2-X07"}],"explanation":["눕힌 기둥은 한 방향으로만 굴러가요.","그래서 여러 방향으로 공을 차기 어려워요.","축구공이 공 모양인 까닭을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#24','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C2',4,'mc','auto','다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?',ARRAY['M1-1-u2-X09','M1-1-u2-X04']::text[],false,'{"seq":24,"concept":"M1-1-u2-C2","difficulty":4,"kind":"mc","stem":"다음 가운데 공 모양에만 맞는 설명은 어느 것인가요?","options":[{"t":"평평한 부분이 하나도 없어요","correct":true},{"t":"굴러갈 수 있어요","mis":"M1-1-u2-X09"},{"t":"뾰족한 부분이 없어요","mis":"M1-1-u2-X04"}],"explanation":["평평한 부분이 하나도 없는 것은 공 모양뿐이에요.","굴러가기·뾰족한 곳 없음은 기둥에도 맞아요.","다른 두 모양에도 대 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_1_math_u2_review_d#25','math',1,1,'u2','','g1_1_math_u2_review_d','unit_review','M1-1-u2-C4',4,'essay','teacher','상자·기둥·공 모양을 하나 이상씩 써서 동물을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M1-1-u2-C4","difficulty":4,"kind":"essay","stem":"상자·기둥·공 모양을 하나 이상씩 써서 동물을 만든다면 무엇을 만들지, 모양마다 어디에 쓸지 까닭과 함께 써 보세요.","answer_guide":{"answer":"예: 강아지를 만들어요. 몸통은 상자 모양 — 평평해서 세워 두기 좋아요. 다리는 세운 기둥 — 몸통을 받쳐요. 머리는 공 모양 — 둥근 얼굴을 나타내요.","scoring_points":["세 모양을 모두 썼는가","모양마다 쓸 자리를 말했는가","평평하다·둥글다 같은 생김새·특징으로 까닭을 댔는가"]},"explanation":["만들 것을 먼저 정해요.","자리마다 필요한 생김새를 떠올려요.","그 특징이 있는 모양을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
